/* 平成24年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h24.committeeSessions.push(...[{"id":"h24-20121127-8","meetingId":"h24-cm11","date":"2012年11月27日","dateIso":"2012-11-27","committee":"建設委員会","time":"午前１０時００分～午後３時３０分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を75件整理しています。","topics":[{"id":"topic-01","title":"の１、附帯決議（案）","agenda":"の１、附帯決議（案）","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この中身を教えていただきたいのが一点と、１番目ですけれども「各特別区がより一層、とらえていいのかという確認をしたいと思っています。２３区統一でやるという形に今はなっていると思うんですけれど、確認をさせていただきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"須藤委員","kind":"意見","question":"もう１つは昨日何かあった……、何かあまり大きなあれではないんだけれども、その２回だったと思います。それから３番目については、各区が独自性を持った制度の方向性を決めなさい、執行していくときには解散しなさいということの意味を持っておりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"１番のところが、品川区だけが個別にできる仕組みでないということを確認させていただければ、賛同をいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"須藤委員","kind":"質問・要望","question":"品川区だけ飛び出していって勝手に何かしようということではなくて、その心意気だけは品川区の中では残しておきたいということの意志を、昨日もお話ししたとおり示していきたいということでの決議文ということで、ご理解ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"}]},{"id":"topic-02","title":"平成２４年請願第１９号、武蔵小山駅周辺まちづくりへの住民参加を求める請願","agenda":"平成２４年請願第１９号、武蔵小山駅周辺まちづくりへの住民参加を求める請願","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"何でこんなに１４２メートルもの高いマンションになるのかということに対して、そういう中で、地域の方々の疑問の声としてあると思うんですね。どういう形でつくられたのか、なぜこういう形で、どこが入っているのかということもお聞かせほしいと求めました。","respondent":"溝口都市開発課長","answer":"繰り返しの説明になりますが、全く意見を聞かないというわけではなくて、そういったものの意見に沿った形でつくってきているものです。コンサルタントについては、日本設計と契約いたしまして、策定を進めてきたものです。","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうことでつくっていくべきだと思うんですけれど、行っていないのであれば、なぜ行わなかったのかということをお聞かせほしいと求めました。こういう指針をつくるんだということなんですけれど、無秩序というのはどういうことを指すのかということも、教えてほしいと求めました。","respondent":"溝口都市開発課長","answer":"対象区域が５６ヘクタール、武蔵小山の林試の森公園、そこの方たちを全員対象にした説明会というのはやっておりません。駅に面した広場の整備、一般的であればまとまったところでマンション建築等を行い、先ほど無秩序なまちづくりが進むということで答えたものです。","id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"地域の方々のご意見としてあるわけですけれども、アンケートが生かされていないのではないかという声に対してはいかがでしょうか。もう一つは、今回１４０メートル級の超高層マンションを４棟建てるというのが、その４棟が合わせてランドマークという表現なんか尋ねました。","respondent":"溝口都市開発課長","answer":"４棟の建物につきましては、一応イメージとして、街並み誘導指針で出しています。それをまちづくりのスカイラインの頂点として、ゆるやかに一般市街地につながっていく、そういった考え方を示しているものです。","id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"公聴会を開いてくださいという要望なんですけれども、そしてご意見を伺うという場をぜひ持つべきだと思うんですけれども、その点についてはいかがか尋ねました。","respondent":"溝口都市開発課長","answer":"先ほどご説明したとおり、区民等への周知につきましては、区の広報およびホームページに掲載して、十分周知をしていますので、改めて説明会を開催するという考えはございません。","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"どうして説明会をされないんでしょうか。まちづくりのビジョンを地域の方に知っていただきたいというのは、区としてはないんか尋ねました。","respondent":"溝口都市開発課長","answer":"全文が見たいということであればホームページで閲覧できるような形で、そういったものもあわせて広報で周知をしておりますので、そちらで住民の方々には周知をしているというのが実情です。","id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう計画なわけですから、それをより多くの方に知っていただきたいというふうには、先ほどお伺いしたんですね。知っていただきたいと思わないのか。","respondent":"溝口都市開発課長","answer":"知っていただきたいという思いで、広報しながわに掲載をしておりますし、ホームページでも公開しています。そういったもので行っているものです。","id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"知っていただきたいという思いがあることをはっきり伺って、とてもうれしく思っています。知っていただきたいと思いながら、地域のどれぐらいの方に知られているかというところでは、区としてはどういうふうに思われているんか尋ねました。","respondent":"溝口都市開発課長","answer":"私どもといたしましては、これまでも品川区のさまざまなお知らせをしてきた広報しながわに掲載することで、十分皆さんに周知というのは図られているというふうに考えております。","id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"一度、この街並み誘導指針をご存じですかということをどこかで聞いていただくなり、とっていただくなり、ぜひともしてほしいと求めました。この武蔵小山の地域の方皆さんに知っていただきたいということであれば、私はぜひとも説明会を開いていただきたいと、改めてお伺いします。","respondent":"溝口都市開発課長","answer":"これまでと同じになりますが、広報しながわに掲載することで、十分周知は図られていると考えています。あわせまして、現在パブリックコメント等も実施しておりますので、そういった中でもまた意見はお聞きできるというふうに考えているものです。","id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"あれだけ２日間にわたって説明会にたくさん来られるわけですから、すばらしい商店街もあり、本当にたくさんいらっしゃると思うんですね。この街並み誘導指針、地域の方に理解をしてもらう、そして地域の方と一緒にまちづくりを進めるという姿勢で進めていただきたいと思うんですけれど。","respondent":"片田都市環境事業部長","answer":"やはりこれからまちづくりを進めていく中では、先ほど申し上げましたようなマスタープランを含めて、地区別の方針を示しております。そういう方針をやはり区民の方と協働して、やはり説明会をやるということではなくて、広報をしていきたいと考えております。","id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"アンケートも生かされていないというのが地域の方の思いですから、武蔵小山のまちを愛する、強く要望をしておきたいと思います。１棟だけだと今回アセスメントの対象にならないということでお聞きしたんですけれど、１棟ずつ建てて、どうなるのかということを説明するよう求めました。","respondent":"溝口都市開発課長","answer":"高さが１００メートル以上、また延べ床面積が１０万平方メートル以上、この両方の条件を超えるものについてはアセスメントの対象になります。アセスメントにつきましては、４つあるからといって、４つまとめてアセスメントの対象になるというものではございません。","id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それが４つ合わさったときには必ずアセスメントの対象になるので、そういうところを求めていくことはできないものなのでしょうか。今回は１４０メートル級が４棟ですけれど、４５メートル、ここの需要をどう考えているかということについても説明を求めました。","respondent":"溝口都市開発課長","answer":"建物を建てていく中での検討になっていくというふうに考えておりますし、事業をしていくように指導していきたいと考えております。周辺地区につきましても、武蔵小山駅周辺というポテンシャルを生かすのであれば、十分需要があると考えているものです。","id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"アセスメントのことについては、建物の風環境とか日影とかはありますけれど、交通量予測というのもされるんでしょうか。荏原地域で受けたんですけれども、需要が十分にあるという根拠を出されているのか、その根拠についても説明を求めました。","respondent":"溝口都市開発課長","answer":"そういったものを踏まえながら、今回のパルム駅前地区については６４０戸の住宅が建てられるというふうに考えておりますので、計画しているものです。そういったものを根拠に、需要は十分あるということをお話しさせていただいているものです。","id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ディベロッパーは、地域のマンションの空室とかそういうものも調べているんでしょうか。区としてそこら辺のところをどう把握されているのか、そこら辺の、区としての把握についてもちょっとお聞かせほしいと求めました。","respondent":"溝口都市開発課長","answer":"ディベロッパーですとかそういった調査会社がヒアリング等を行いながら、現在の需要はどうなのかというのを判断しながら進めてきているものです。今回のパルム駅前地区につきましては十分、立地条件等を勘案して６４０戸の住宅の建設は可能だというふうに、判断しているものです。","id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"大崎で何千戸、進めているのかどうなのかというところを聞いているので、この根拠も含めてお聞かせほしいと求めました。６０メートル、なぜ４棟の１４０メートル級の超高層や６０メートル級の高層建築物群が、根拠をお聞きしたいと思います。","respondent":"片田都市環境事業部長","answer":"その結果として、区としてもそれを支援するという立場から、計画に対しての都市計画的な手法等々についてのご相談に対応させていただいて。４棟ということについても、今後地域の方々がそういうまちづくりを進めていく上で、十分検討した中でご提案されてくるものと考えています。","id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"航空法というのは法律ですから、守らなければならない最低限のものですから、それこそ乱開発になってしまうのではないかと思うんですね。街並み誘導指針もしっかりと、地域の方の合意が得られるような形で、説明会を開いていただきたいということを強く要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"木村委員","kind":"質問","question":"ですから、今の武蔵小山、もしくはこの品川区の各まちすべてにおいて、その住民は今のまちに対して、それを守っていきたいと思っていると思うんです。その点、区のほうではどのように考えますか。","respondent":"溝口都市開発課長","answer":"３・１１を契機に、防災性の向上のため一日でも早く改善したい、そういった中でどのような形のまちづくりを進めていけばいいのかと。","id":"exchange-020"},{"speaker":"木村委員","kind":"質問","question":"デザインのやり方によって、その風害を抑えることができる建て方があるということを聞いたことがありますけれども、そういうことはご存じでしょうか。そういうものが取り入れられるかどうか、答えるよう求めました。","respondent":"溝口都市開発課長","answer":"風害等がなるべく少なくなるように、そういったことを指導して、現在計画に至っているものです。","id":"exchange-021"},{"speaker":"木村委員","kind":"意見","question":"そういう意味では、新しい開発をすることによって、そういうものを随所に残していくということは大変大事だと思っているんです。そういう計画があるかも説明を求めました。","respondent":"溝口都市開発課長","answer":"武蔵小山はアーケードのある商店街というのが一つの特徴だと考えています、商店街の連続性を配慮して空地等はあまり設けずに、建物の配置計画等をしているものです。","id":"exchange-022"},{"speaker":"浅野委員","kind":"質問・要望","question":"その中で確認したいことが何点かありますので、それらについて教えてほしいと求めました。このようなことというのは、当てはまるかと思うんですけれども、区としての認識はどうお持ちなのか、改めてお伺いします。","respondent":"溝口都市開発課長","answer":"そういった中で各所有者の方、また使われている方の負担で直すというのは、非常に大変なことだと考えています。そういった地域の課題を解消していくために、今回、再開発事業という形での都市計画を定めるということで動いているものです。","id":"exchange-023"},{"speaker":"浅野委員","kind":"質問","question":"この地域に本当に愛着があるというんでしょうか、ずっと住み続けたいというふうに思っている方なんですね。特に防災に関しての地権者の方のご意見と、そして周辺の住民の方からのご意見など、ちょっとかいつまんで教えてほしいと求めました。","respondent":"溝口都市開発課長","answer":"まず地権者の意見ですが、３・１１を契機に一体どういう形でまちづくりを進めていったらいいか、住んでいても非常に危険でという話は聞いております。何かあったら危険、または避難する際にどうかというお話を聞いている中で、今回の事業計画を進めているものです。","id":"exchange-024"},{"speaker":"浅野委員","kind":"質問・要望","question":"これ以上どうするのかという問題は別といたしまして、そういう意味では、今回の件に限らず進めていっていただきたい。地域の方が本当に住みやすいまちづくり、安全なまちづくりということで進めていってほしいと求めましたので、よろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"須藤委員","kind":"質問","question":"その後、逆にでき上がってからは非常に協力的になって、そこの自治会の会長になったというような話もちょっと伺ってきたんですけれども。今度の武蔵小山駅周辺についても、今までと同じように丁寧にやってこられたのかどうか、それを説明するよう求めました。","respondent":"溝口都市開発課長","answer":"再開発につきましては、どの地域も同じように進めてきております。ですから丁寧に説明はしてきておりますし、計画案の段階からも説明会をしておりますし、地区内につきましては説明会を開きながら。","id":"exchange-026"},{"speaker":"須藤委員","kind":"意見","question":"ここについてもそういうことはしっかりとした過程を経て、安心・安全な、そしてきれいなまちにしてもらえればと。まちのコミュニティというのがつくられているという、そういうものがつながるような仕組みだけはつくっておいてもらえるようにお願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"吉田委員","kind":"質問","question":"１点だけお伺いしたいんですけれど、こういうことを聞いていいのかとか、そういう話になってきちゃうと思うんですね。その点はどうお考えか尋ねました。","respondent":"溝口都市開発課長","answer":"そういったもので周知を図っておりますし、開発計画または別の事業等においても同じように、街並み誘導指針などついてもご説明してきているものです。ですからこれまでと同じように、再開発事業等の中でも説明はしていきたいと考えています。","id":"exchange-028"},{"speaker":"吉田委員","kind":"質問","question":"いいまちをつくっていく、愛するまちにしていくということが必要なのではないかと思ったものですから、ちょっとお話しさせていただきました。その辺、もう一度お願いします。","respondent":"片田都市環境事業部長","answer":"これまでもいろいろな手だてを使って説明してきたところですけれども、委員ご紹介いただいたような提案についても十分検討させていただいて。","id":"exchange-029"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"地域の方から説明をしてほしいということで求められれば、区としてぜひ応じていただきたいと思うんですけれど、この点はいかがか尋ねました。","respondent":"溝口都市開発課長","answer":"基本的には広報の中でお知らせしているものです。ただ、パルム商店街とかそういったところで改めてというお話であれば、それについては説明をしていきたいと考えております。","id":"exchange-030"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私が聞いたのは、商店街の関係者とか町会長というところには、今までも話してきているわけなので、そうでなくて地域に住んでいる方、住民の方々がぜひ区に説明を求めたいといったときに応えていただきたいと、そういうことで伺ったんですけれど。","respondent":"溝口都市開発課長","answer":"今までも策定経緯の中で、町会、自治会または商店街等についてヒアリング等を行いながらつくらせていただき、その結果としてお話を聞きたいというところがあればご説明をしてきた、そういうふうに考えているものです。","id":"exchange-031"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私がお聞きしているのは、今までやってきた代表の方々ということではなくて、一般の地域の住民の方々から説明会をしてほしいというふうな要望があったとき、応えていただきたいということなんですけれど。","respondent":"溝口都市開発課長","answer":"すみません、一般の方向けにつきましては、広報しながわまたはホームページといったところに掲載しておりますので、そちらをごらんいただきたいというふうに思っております。","id":"exchange-032"},{"speaker":"須藤委員","kind":"意見","question":"ここで危惧していることもいろいろあろうかと思うんですけれども、最終的には開発を見直してくださいということなので、ちょっと願意には沿いがたいということですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"},{"speaker":"浅野委員","kind":"質問","question":"請願項目について先ほど質問の中でも出させていただきましたけれども、須藤委員と同じになりますけれども、武蔵小山駅周辺再開発の見直しということについては、やはり願意に沿いがたいということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"地域の住民の方が求めたときには、私はそういう態度はぜひとも改めていただいて、区民の皆さんへの説明会ということに応えていただきたい。そういうことを、ここで採択をして、ぜひとも区にしていただきたいと思っていますので、採択を主張します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"}]},{"id":"topic-03","title":"平成２４年請願第２０号 区内を循環するコミニティバスの運行を求める請願","agenda":"平成２４年請願第２０号 区内を循環するコミニティバスの運行を求める請願","exchanges":[{"speaker":"須藤委員","kind":"提案","question":"補助２６号線が全部開通したり何かすれば、交通会社ともその辺を意見交換しながら、民間でやってくれる状況になったらまた提案していきたいなと。現状ではなかなか難しいということなので、今日結論を出してほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-036"},{"speaker":"浅野委員","kind":"提案","question":"コミュニティバスについては、公明党からも第３回定例会で提案をさせていただきました。そういう意味で私どもが提案したのは、実際にどうしていったらいいのかということを検討して、次の段階に進むというふうに考えておりますとの意見を述べました。","respondent":"藤田都市計画課長","answer":"例にございました補助２６号線ですとか、補助１６３号線ができ上がった場合、今後そういう会議体についての設置に向けた検討を行いまして。地域公共交通会議については、設置に向けた検討をこれから行っていきたいと考えています。","id":"exchange-037"},{"speaker":"浅野委員","kind":"質問・要望","question":"区民の利便性も図りながら、その会議の中で検討を進めていって、最善の解を求めていってほしいと求めました。ここのところは意見ですので、もしお考えがあれば、シルバーパスに関していただければと。","respondent":"藤田都市計画課長","answer":"そういう中で、区のほうとしてもいろいろな場面で、福祉面では、福祉タクシーですとかそういった事業も行ってあります。そういった事業も重ね合わせた上で、地域の公共交通のネットワークがしっかり結べていければいいなと、このように考えているところです。","id":"exchange-038"},{"speaker":"吉田委員","kind":"質問","question":"この請願に、１時間に数本しかありませんという訴えがあったんですけれど、この実態というのをお聞きしたいなと思いまして、お願いします。","respondent":"藤田都市計画課長","answer":"ですから上り、下り合わせると４本のバスは通っていることになりますけれども、本数は現状では少ないのかなと考えています。例えばバスの増便等の検討はできないのか、そういった形のことをまずは私どもが申し入れるのが、一番先の手だてかなと考えています。","id":"exchange-039"},{"speaker":"吉田委員","kind":"意見","question":"今、おっしゃっていただいたので、それはやはり一番先に、道路の見直しとかいろいろありますけれど、最初に京浜急行バスのほうにお話をしていただくような形で、第一歩を進んでいけるのではないかと私も思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-040"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"党の議員からも検討会議をぜひとも設置してほしいということを要望もしてきたんですけれども、今、浅野委員の要望に応えて。前回の平成２３年２月の請願審査のときから、２３区の中で増えているところがあったら、そこの実態も教えてほしいと求めました。","respondent":"藤田都市計画課長","answer":"当時と今で、私が説明している数は変わっていません。それから豊島区については、コミュニティバスの導入ということでずっと検討会を重ねてきています。","id":"exchange-041"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"全くこういう形でやっていないのは品川区と港区だけという、２区だけということになるのか、その確認をお願いします。例えばしながわ水族館のバスを、そういうようなことからでも開始できないかという要望もいただいたんですけれど、そこら辺はいかがか尋ねました。","respondent":"藤田都市計画課長","answer":"補助１６３号線ですとか補助２６号線など、公共交通ネットワークを検討する必要があるというふうに区のほうでは考えてあります。検討したほうがいいのではないかというお話をしながわ水族館にしたんですが、議論をして、今の運行形態にしたものです。","id":"exchange-042"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"こういうものが品川区にもあったらいいのにということをいつも伺っているんですけれども、利用して実感しているというのがあると思うんですね。どれだけ便利に、ぜひこの地域公共交通会議を設置する中で、実現に向けていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"浅野委員","kind":"質問","question":"質問の中でも教えていただきましたけれども、具体的な路線については、この場で採択というわけにはいかないと思います。シルバーパスについてもその中で検討になると思いますので、今回は願意に沿いがたいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"}]},{"id":"topic-04","title":"を行います。 初めに、(1)専決処分の報告","agenda":"を行います。 初めに、(1)専決処分の報告","exchanges":[{"speaker":"須藤委員","kind":"質問","question":"３年前の２月１５日に天井板が落下する事故が起きたというのは、何でこんなことがあったんか尋ねました。","respondent":"大串住宅担当課長","answer":"こちらの２月１５日に発生した件ですが、この方が住んでいる上階の部屋の漏水によるものです。この漏水の原因につきましては、上の階の方の洗濯機の排水板のところに不具合があったため、起こったものです。","id":"exchange-045"}]},{"id":"topic-05","title":"品川駅南地域 まちづくりビジョン 中間まとめ","agenda":"品川駅南地域 まちづくりビジョン 中間まとめ","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この品川駅南地域ということで９２ヘクタールということなんですけれど、教えてほしいと求めました。そしてこれは、中間まとめから取りまとめまでは、どのようにこれを地域の方に知らせて意見を求めていくのかということについても説明を求めました。","respondent":"溝口都市開発課長","answer":"中間まとめについてどのように地域の方にということですが、先ほど来説明がありましたように、当地区につきましては推進協議会が立ち上がっています。当計画につきましては、東京都等関係部署とも十分調整しながら、最終的な取りまとめを作成していきたいと考えているものです。","id":"exchange-046"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"区民へのお知らせというのはどういうふうにするのかということと、意見を求めていくべきだと思うんですけれど、そこら辺の考えもあわせて説明を求めました。","respondent":"溝口都市開発課長","answer":"策定した暁には、当然ホームページですとか広報、そういったもので周知を図っていきたいと考えております。先ほどの推進協議会には、そちらの方たちと十分お話をしながら、取りまとめに向けて進めていきたいと考えているものです。","id":"exchange-047"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この推進協議会のメンバーはどういう方で、何人ぐらいいらっしゃるのかということを教えていただきたいのと、推進協議会というのはまち全体から選ばれた人ということなのか、そこら辺のところも含めて教えてほしいと求めました。","respondent":"溝口都市開発課長","answer":"メンバーとしては全員で５７名、企業等を含めますので５７の個人または団体、会社等が入っているものです。自治会長、そういったところでしっかりと説明をし、ご意見を聞きながら取りまとめをつくってきたというふうに考えているものです。","id":"exchange-048"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"多様な主体の参画・協働によって発展する街ということを掲げているわけですから、その点についてもお聞かせください。ここの９２ヘクタールの中に幾つの都営住宅が入っていて、それがどうなっていくのかということも、あわせて説明を求めました。","respondent":"溝口都市開発課長","answer":"冒頭の説明にもありましたように、当地区も含めてまちづくりをどうするのかというのが、町会長連盟から要望書が出されています。まずはご意見を聞きながらというのが、私たちとして進めていくべき手法だと考えておりますので、そのような形で考えているものです。","id":"exchange-049"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１万３,９２０人以上いるという中で、そこのところがこの計画の中ではどう位置づけられているのかということをお聞かせください。これも多分コンサルタントが入ってつくられていると思うんですけれど、そのコンサルタントはどこなのかということも教えてほしいと求めました。","respondent":"溝口都市開発課長","answer":"ですから、すぐに都営住宅を動かすとか、何かしていくという考えはございません。東京都が今後どういう形で都営住宅を考えるか、そういったものを十分聞きながら、まちづくりをすすめていかれるというふうに考えているものです。","id":"exchange-050"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"かなり切実に求められているところですので、絶対にここをなくすというふうなことはしないまちづくりをしてほしいと求めました。１万３,９２０人、改めて私は全地域の方々を対象にした説明会をぜひ開いていただくように、強く要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"沢田委員","kind":"意見","question":"可能性というか話し合いというか、そういったことはどの程度進んでいるのかというのと、どういったところでその辺が考えられていらっしゃるのかというのを説明するよう求めました。","respondent":"溝口都市開発課長","answer":"アセスメントが行われている段階で、具体的な駅の位置、またどういう形で出口を設けるのかというのは決まっていないというふうに聞いております。","id":"exchange-052"},{"speaker":"沢田委員","kind":"質問","question":"さらなる水辺の拠点ということで書かれていますけれども、いろいろ利用が進むといいなと思っているんですけれども。あわせてこの水辺の近隣の整備ということを考えられているかと思うんですが、その辺もこういうところに含まれているということでよろしいか尋ねました。","respondent":"溝口都市開発課長","answer":"羽田空港に不定期利用できるような桟橋が設置されている状況がありますので、水辺の利活用を図っていきたいというふうに考えて、このまちづくりビジョンをつくっているものです。","id":"exchange-053"},{"speaker":"沢田委員","kind":"質問・要望","question":"近隣の区もいろいろ、港区も江東区も水辺がある、運河がある区とも協力を進めながら、こうやって水辺の開発というのはさらに進めていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"浅野委員","kind":"提案","question":"どの程度というんでしょうか、それとも何か協議会から提案されたことで大きく変わった点とか、教えてほしいと求めました。","respondent":"溝口都市開発課長","answer":"地元が提案してきた構想を踏まえるような形で作成しておりますので、大きな違いはないというふうに考えているものです。ここに書かれている拠点の考え方ですとか軸、ゾーニングの考え方、今回中間まとめとしてビジョンをまとめているものです。","id":"exchange-055"},{"speaker":"浅野委員","kind":"質問","question":"どうももうちょっと、そういうものについては、全体的にどんなものだろうと考えられているのかなと。個別にあれば教えてほしいと求めました。","respondent":"溝口都市開発課長","answer":"もう一つは品川浦という水辺がある、そういったものが当地区の特徴だと思っています。賑わいの持てるようなまちづくりを進めたいと考えておりますし、水辺の魅力づくりに取り組んでいく、そういうふうに考えて進めているものです。","id":"exchange-056"},{"speaker":"浅野委員","kind":"質問","question":"それにふさわしいというんでしょうか、応えられるような形を、ぜひとも考えてほしいと求めました。これはどうしても時代の流れとしてはしようがないのかなとは思いますけれども、そういう取り組み、その点についても一言お願いできればと思います。","respondent":"溝口都市開発課長","answer":"地元でも協議会を立ち上げてさまざま取り組んでいるところで、新たにそういった古い歴史的なものを感じられるようなまちづくりを進めていくと。","id":"exchange-057"}]},{"id":"topic-06","title":"第二次品川区環境計画（素案）","agenda":"第二次品川区環境計画（素案）","exchanges":[{"speaker":"浅野委員","kind":"質問","question":"ぜひ広く意見を聞いていただければと思うんですが、私の意見も少し酌んでいただけたらと思いながら、質問します。私も一般質問で、整合性をとるようにしたらどうかという質問をさせていただきましたけれど、その点について説明を求めました。","respondent":"野呂瀬環境課長","answer":"来年の３月に環境計画を策定するのとあわせて、地域センターとか、いわゆる区内に施設があります。そういう方向性で今考えているところです。","id":"exchange-058"},{"speaker":"浅野委員","kind":"確認","question":"品川区としては、実質的にはもうＣＯ２に絞って削減をしているというふうに伺っていたんですが、二酸化炭素にすべきではないかと私は思います。それを品川区としては確認しながらやられていると思うんですけれども、例えば２３ページ、途中で切れていて次のページになっているんですね。","respondent":"野呂瀬環境課長","answer":"自転車道の整備状況」の２つ合わせてということになっていますので、自動車道の整備状況」となると「２０％前後」なのかなということなんです。パブリックコメントに向けては、本当に間違いのないような形にしていくつもりですので、よろしくお願いいたします。","id":"exchange-059"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"１２月１２日からパブリックコメントが始まるんですけれど、このパブリックコメントをとるに当たっての区民への周知というのは、どういう形にするのかを説明するよう求めました。","respondent":"野呂瀬環境課長","answer":"はホームページ等で、周知徹底を図ってまいります。閲覧場所につきましては、環境課の窓口、区政資料コーナー、図書館、各地域センター、環境情報活動センター等です。","id":"exchange-060"}]},{"id":"topic-07","title":"品川区一般廃棄物処理基本計画（第３次・素案）","agenda":"品川区一般廃棄物処理基本計画（第３次・素案）","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１７年、１２年というふうに逆の並び方になっていて、このグラフは統一をしてもらったほうがいいかなというのが一つ思いました。基本的なところで教えていただきたいんですけれど、この再生処理工場というのはどこなのかというのを一つ教えてほしいと求めました。","respondent":"太田品川区清掃事務所長","answer":"これはご案内のとおり本格実施が平成２０年１０月から、分別変更に合わせて実施させていただいたところです。義務づけられている事業者がみずから再商品化を実施するか、ということで、ほとんどは指定法人に委託をしております。","id":"exchange-061"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"やはりこれからもごみ減量というのは本当に求められていくと思うんですけれど、この概要版の３ページのところにきれいにカラーで。国では平成２２年に「バイオマス活用推進基本計画」に基づいて云々とあり、区としての考えがありましたら、あわせて教えてほしいと求めました。","respondent":"太田品川区清掃事務所長","answer":"年末にごみ・リサイクルカレンダーを配っているというのも実施してきてありますけれども、それだけではなくて、今年度から精力的にやっています。現実的な対応としては、あるいは水切りを徹底していただくとか、生ごみの処理機を使っていただきながら減量していただくとか。","id":"exchange-062"}]},{"id":"topic-08","title":"河川活用交流事業支援（目黒川乗船見学会）","agenda":"河川活用交流事業支援（目黒川乗船見学会）","exchanges":[{"speaker":"浅野委員","kind":"質問・要望","question":"子どもたちもどうしてもいろいろと動きたいとか、事故が起きないような安全対策というのはきっちりされていると思うんですけれども、その点についてちょっと内容をお聞かせほしいと求めました。","respondent":"武藤河川下水道課長","answer":"あわせて実施機関でありますしながわ観光協会には、実施当日に、例えば万が一大雨が降ったときの対応だとか。そういった安全対策をとりながら、乗船する皆様にはしっかり楽しんでいただければと考えています。","id":"exchange-063"},{"speaker":"須藤委員","kind":"質問","question":"さっきイルミネーションを見ると聞いて、そこまでやるのかと思ったんですけれど、どういうふうに見るつもりですか。その辺のあれは、何でやるんか尋ねました。","respondent":"武藤河川下水道課長","answer":"こういった事業は今回初めてなので、実施状況を見ながら、また今後検討していきたいと思っています。実は船の出航が大体３時半ごろを予定しておりまして、まだ明るい時間帯ですので、施設等を見学できる状況です。","id":"exchange-064"},{"speaker":"須藤委員","kind":"意見","question":"ぜひ子どもたちが水辺に親しむようなあれを、こういった支援金というものを、できるだけ時期も選んで使ってくださいとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-065"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この河川活用交流事業支援金の中身をちょっと教えていただきたいんですけれど、国からの支援金ということだと思うんですけれど、子ども２０名の６日間で１２０名で、どれぐらいの予算なのか、これから毎年これを続けて活用ができるのかというあたりも含めて、説明を求めました。","respondent":"武藤河川下水道課長","answer":"来年度以降ですけれど、またそれは今後、こういった実施状況を見ながら考えていきたいと考えています。今回、本事業に対しましては、必要最小限の、実施する部分の直接経費につきまして、約５０万円を支援している形になっております。","id":"exchange-066"}]},{"id":"topic-09","title":"耐震改修促進計画の改定における耐震化率","agenda":"耐震改修促進計画の改定における耐震化率","exchanges":[{"speaker":"木村委員","kind":"質問","question":"その他の施設というのが７９％になっていますけれども、この防災上重要な施設のマイナス８.２ポイントはどういう施設とか、どういう建物でしょうか。説明を求めました。","respondent":"品川防災整備担当課長","answer":"ちょっと詳しいことはわかりませんが、学校等、保育園、地域センター等で少し終わっていないところがあるというような報告は聞いております。それからその他の施設ですが、高齢者福祉施設とか公園管理施設等が、こちらのその他の施設に入ります。","id":"exchange-067"},{"speaker":"木村委員","kind":"意見","question":"特に今言われたようにその他の施設で２１％マイナスということですが、そういうところを早急にというか重点的にやるお考えはもちろんあると思いますけれど、一応お答えくださいとの意見を述べました。","respondent":"品川防災整備担当課長","answer":"こういった公共の施設というのは災害時の避難所等にもなりますので、非常に重要な施設ですので、早急に耐震化率を上げていくように努力いたします。","id":"exchange-068"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"重点施策のところで木造住宅、非木造住宅と耐震化の支援があるんですけれど、その中でも、木造住宅の耐震化というのは本当に緊急に進めていくことが大事だと思うんですけれど、この支援策を、新たな計画に向けて充実をさせるというところでの区の考え方というのはいかがか尋ねました。","respondent":"品川防災整備担当課長","answer":"こういう関係で、区の耐震化の政策としても、木造住宅は基本的に重点的にやっていきたいと考えております。やはり耐震をしていただく、かつ不燃化対策も同じような効果が出るような手法で、助成をしていく部分を充実させていきたいと考えております。","id":"exchange-069"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"不燃化も合わせてですけれど、そういうところでの助成の充実もぜひ、プラスでやっていただきますように要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-070"},{"speaker":"浅野委員","kind":"質問","question":"その点が１点と。裾野を広げていくという考え方でどうなのかということですとか、そういうことについても今後の考え方を教えてほしいと求めました。","respondent":"品川防災整備担当課長","answer":"こういった点も含めて、今後どういった助成をしていったらいいかということは検討していきたいと考えております。こういった状況も踏まえて、今後検討していきたいと考えております。","id":"exchange-071"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"全面改修したときに建築確認についてもやって改築をしたので、それがぎりぎり昭和５６年を超えて、全くの助成を受けられないという声を聞きました。ぜひそういうところにも支援を増やしていただきたいと思うんですけれど、いかがか尋ねました。","respondent":"品川防災整備担当課長","answer":"これが昭和５６年６月以降ですと、基本的には地震に耐える建物でないと、建築確認が通らないということになっております。昭和５６年６月以降に建った家に対して、助成を行っていくというのは、非常に難しいというのが現状です。","id":"exchange-072"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"確認をとっているにもかかわらず、それは確認をおろしたところの問題になるのか、どうなのかわからないですけれども。確認はとられているわけですから、それで建てたわけですから、ぜひそれは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-073"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"でも数十年前のことだから。実際やはり困っているということなので、ぜひご検討いただいて、受けられるようにしてほしいと求めましたけれど、だめですかね。","respondent":"片田都市環境事業部長","answer":"私のほうからお答えしますと、昭和５６年６月以前のものについては、昭和５６年以降の建物であれば大きな被害は出ていなかったと。補強方法の考え方とか、助成の対象には、残念ながら今の時点ではしていないというのが実態です。","id":"exchange-074"},{"speaker":"木村委員","kind":"質問","question":"概要版のほうで耐震化の目標が書かれていますね。これは１００％を目指すのが当たり前だと思うんですけれども、９０％以上というのはどうしてか尋ねました。","respondent":"品川防災整備担当課長、片田都市環境事業部長","answer":"なぜ目標が１００％でないのかという点ですが、こちらは耐震改修促進法という法律があります。今回、東京都のほうが９５％という形で出ておりますので、それに連動した形で目標を挙げております。そういう中で新たに耐震改修促進法の改正を行って、たしか平成１８年あたりには、国のほうの方針として一応９０％を目指すと。","id":"exchange-075"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/142731?Template=document&Id=4060#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":73716,"voices":238}},{"id":"h24-20121127-9","meetingId":"h24-cm11","date":"2012年11月27日","dateIso":"2012-11-27","committee":"文教委員会","time":"午前１０時００分～午後３時１４分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を53件整理しています。","topics":[{"id":"topic-01","title":"の(1)平成２５年度入学希望申請の状況","agenda":"の(1)平成２５年度入学希望申請の状況","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"今までの数字からすると、どういうふうに見たらいいのか、それを教えていただきたい。とりあえずそれをお願いしたいと思います。","respondent":"和氣学務課長","answer":"昨年よりは待機は増えているという結果になっております。","id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"どういう傾向にあって、どういうふうに教育委員会としては見ているかということについて教えてほしいと求めました。小学校が４校ぐらいだったかしら、増えているということで終わらないで、具体的な説明をしてほしいと求めました。","respondent":"和氣学務課長","answer":"冒頭で説明したとおりです。こういう状況の中で、私どもとしてはそういう子どもをどれだけ就学させるかのほうにどちらかというと関心が強くなっているところです。","id":"exchange-002"},{"speaker":"伊藤委員","kind":"質問","question":"だから、ハードはすぐつくれないことはわかっているけれども、次のステップを考えたらどうですか。これだけ抽選で待たされているわけだから、こういうふうにいつもなるんですが、改めてお考えを説明するよう求めました。","respondent":"和氣学務課長","answer":"例えば校庭にプレハブを建てて、それで入れるかと、これもまたそれぞれの区役所の関係においてマイナスになってしまいます。最終的に人口増に対する教室不足がありますので、その部分で今後しっかり検討させていただいて、改めて検討してまいりたいと考えているところです。","id":"exchange-003"},{"speaker":"伊藤委員","kind":"質問","question":"難しいことはわかりますし、あえて申しているのですけれども、確かに、だけれども、毎年毎年、私たちに来るのは同じような話なんです。もともと公立で抽選はあり得ないんですから、それに対してハード部分でしっかり答えを出していく必要があるのではないでしょうかということで。","respondent":"和氣学務課長","answer":"繰り返しになってしまいますが、ハード面も含めた検討をしているところでございまして、今もしていますけれども、しっかり子どもたちが希望の学校に入れるように、いろいろ考えて、知恵を出してまいりたいと考えています。","id":"exchange-004"},{"speaker":"伊藤委員","kind":"質問・要望","question":"私立よりも区立の小・中学校を選んだわけですから、この中でできるだけ保護者の方々に対する理解の促進、今はそれしかできないですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"阿部委員","kind":"質問","question":"これは６歳児の人口ですから、それを特にどういうふうに吸収しようと考えていらっしゃるのか、学区の学校に入り切れないですよね。今後の見通しについて、品川区教育委員会として、どのように考えていらっしゃいますか。","respondent":"和氣学務課長","answer":"実は２３区平均、小学校整備が４,０００人から５,０００人分は転出がないと増えてしまう、そういう推計になりつつあります。そこも含めまして、今後十分検討して、早いうちに方針を示していくというふうに思っております。","id":"exchange-006"},{"speaker":"阿部委員","kind":"質問","question":"例えばどういうことを考えていらっしゃるのか、今の段階で言えることだけで構いませんので、見通しとともに教えてほしいと求めました。これは来年度以降の保護者の選択にも大きくかかわってくる部分ですので、ぜひお考えを聞ければと。","respondent":"和氣学務課長","answer":"これはまだ内部で、私どもの課の中で検討しているものですので、それを含めまして、基本的には全体で検討していただくというような形で思っておりますが、まだ課内での内部検討ですので、その内容については控えさせていただきたいと思います。","id":"exchange-007"},{"speaker":"阿部委員","kind":"質問・要望","question":"ありがとうございましたというか、控えるような話なのかなと思うんですが、これは、つまり教育委員会の中だけで話していることなんでしょうか。むしろ、教育委員会だけでない検討をしていただきたいと思うんですけれども、その辺はいかがか尋ねました。","respondent":"和氣学務課長","answer":"もちろんシミュレーションをやっていますので、その対策は別にして、どのぐらい増えていくかをシミュレーションし、区長部局にもその情報提供をしていまして、こんなふうな状況になってありますということで、対策が求められますというような話はしています。","id":"exchange-008"}]},{"id":"topic-02","title":"の(3)区立八ツ山保育園の耐震化工事ついて","agenda":"の(3)区立八ツ山保育園の耐震化工事ついて","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"そのあたりを確認したいので教えていただきたいのと、丸々２年間という感じかなと見るんですけれども、そこを教えてほしいと求めました。この委員会だったかどうか忘れてしまったけれども、その辺の心配をする必要はないかなと思ったんですけれども、さっき言った２点について。","respondent":"立川保育課長","answer":"これは長目の設定ということで２年になっておりますが、これまでの実績でいいますと、おおむね１年程度ということになるかと思います。平成２６年１月以降に移ることから、現在、その場所を候補地の一つとしております。","id":"exchange-009"},{"speaker":"南委員","kind":"質問","question":"この２年間の間、１年ぐらいに縮小することもあり得ると理解していいのかどうか、どこでしたか。そこら辺、旧品川・大崎土木事務所だけだと位置的によくわからないので、どこかを説明するよう求めました。","respondent":"立川保育課長","answer":"先ほど説明したとおり、東京都で本年と来年に実施設計をするということになりますので、２年を予定しています。もう１点、旧品川・大崎土木事務所ですが、ここにつきましては、北品川の船どまりの運河、海岸の船清ビルの隣になります。","id":"exchange-010"},{"speaker":"南委員","kind":"質問・要望","question":"全工事移転期間というのは最大限２年というところ、この関係で、位置の確認をしたいと思いました。東京都が実施することではあっても、この期間、事故もなく、しっかりやっていただきたいということを改めて申し上げておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"阿部委員","kind":"質問","question":"幾つかお伺いしたいと思います。それから引っ越しにかかわる経費とか、仮設にかかる経費とか、その辺はどのようにやっていかれるんか尋ねました。","respondent":"立川保育課長","answer":"耐震改修にかかわる経費につきましては、全額東京都持ちです。仮設への引っ越し、また仮設の費用につきましては、現在のところ、区費ということになっております。","id":"exchange-012"},{"speaker":"阿部委員","kind":"意見","question":"耐震は保育園部分、でき上がった後の内装なんかは変わることになるのかしら。耐震で何かくっつけるだけで、中身は全く変わらない状態でまたオープンみたいな感じか、その辺のイメージをとの意見を述べました。","respondent":"立川保育課長","answer":"耐震改修工事にかかわる部分につきましては、東京都が実施なので、改修後、そのまま使えるのであれば、そのままというふうに現在のところは考えております。","id":"exchange-013"},{"speaker":"阿部委員","kind":"質問・要望","question":"私も八ツ山保育園の中がどうだったか、幾つか質問したいのですが、ぜひこの工事についても考えてほしいと求めました。もう一つ、建物自体は保育園にはそぐわないもので、プレハブか何かを建てるんか尋ねました。","respondent":"立川保育課長、金子子ども未来事業部長","answer":"は１点目の、内装等の改修も含めた対応について、これにつきましては、継続いたしまして対応したいと考えております。基本的にはその仮設につきまして、新たに仮設を利用して有効活用を図りながら… ２点目のご質問の仮設の大崎在宅サービスセンターですけれども、今の段階では候補地の一つとして考えておりますので、どのようにやっていくかということも確定していきたいと考えております。","id":"exchange-014"},{"speaker":"阿部委員","kind":"質問・要望","question":"３点目、潜在的な利用希望者に対するお知らせというのは、ぜひ早い段階でやってほしいと求めました。これは、この時期ですので、また要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"南委員","kind":"確認","question":"あるいはどうだったのかということを確認したいのと、建物そのものを耐震化して強度を強化するわけですから、もとのままというふうには。子どもにだって不便をかけるわけですから、改装というのは行うべきだと思うんですけれども、そのあたりを確認したいと思います。","respondent":"立川保育課長","answer":"八ツ山保育園につきましては、これまで大規模改修は実施しておりません。補強に伴って改修を進めるべきではないかというご意見ですけれども、今後は施設の状況等を勘案いたしまして、考えていきたいと考えています。","id":"exchange-016"},{"speaker":"南委員","kind":"確認","question":"大規模改修というのは何年に１回ぐらいのペースでしたかしら。そこを確認したいのと、４１年もたっているから、伺います。","respondent":"立川保育課長","answer":"計画的に現在進めているところですので、それほど老朽化していないというところで、これまで大規模改修については実施しなかったということで認識しています。","id":"exchange-017"},{"speaker":"南委員","kind":"質問・要望","question":"八ツ山保育園って小規模な保育園で、都営住宅が、ここにあるように下に位置している保育園で、潮風も吹く、そういう地域にありますよね。そういう判断をしたことなのかというのを確認したいのと、そこもなかったので、改めて教えてほしいと求めました。","respondent":"立川保育課長、金子子ども未来事業部長","answer":"１９７０年開設で、１９９４年に大規模改修をかけたということで、何年に１回というようなルールというものは決まっていないところです。必要な老朽あるいは劣化が生じた場合には必ず対応しているようにしていますので、この間、耐震工事を実施してきましたけれども。","id":"exchange-018"},{"speaker":"南委員","kind":"質問・要望","question":"それぞれの部分、部分によって、パーツによって改修するということは、それはそれで合理的だと思うんです。４１年もたっていれば劣化もしますし、２年間も工事でご不便をかけるというところもありますし、きちんとした対応をしていただきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"}]},{"id":"topic-03","title":"の私立保育園の移転","agenda":"の私立保育園の移転","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"そのあたりの事情を教えていただきたいのと、１年数カ月後に移転をするということなので、そのあたりを教えてほしいと求めました。評価をしたいと思って、見守っていきたいと思っていますけれども、先ほどのところについてはどういうふうになっているのかをお伺いしたいと思います。","respondent":"立川保育課長","answer":"東京都との協議等におきまして、まだ正式に終わっていないということで、予定ということで書かせていただいております。こちらは聞いているところによりますと、現在、駐車場で利用されているところを新規に建設されて保育園を継続して運営していくです。","id":"exchange-020"},{"speaker":"南委員","kind":"確認","question":"そういう点で１年３カ月程度のことで建設し、準備していくということが十分可能だと見ていていいということなんですか。そのあたりを確認したいと思います。","respondent":"立川保育課長","answer":"いわゆる新規、移転、開設ということで、ほとんど細かいところまで詰めている状況ということで伺っておりますので、あと１年４カ月ほどありますので、再来年４月の開設には間に合うとお伺いしております。","id":"exchange-021"},{"speaker":"伊藤委員","kind":"質問","question":"行政はどういうふうにかかわって、要するに区民の方々に対する情報提供も指導するところがあると思うんですけれども、そのお考えはどうでしょうか。説明を求めました。","respondent":"立川保育課長","answer":"移転先等についても、できれば、区としましては待機児童が多いところに移転していただきたいというところもお話ししています。","id":"exchange-022"},{"speaker":"伊藤委員","kind":"確認","question":"だから、そういういろいろな、マネジメントというか、そういうことについて業者のほうとどのようにかかわっていますかということを確認したいんです。いかがか尋ねました。","respondent":"金子子ども未来事業部長","answer":"在園の方々、それから新しい申込者の方々に説明をしなければならないということがありましたので、それに先だって委員会にご報告申し上げているです。","id":"exchange-023"},{"speaker":"伊藤委員","kind":"質問・要望","question":"要望です。認可保育園ですから、ぜひしっかり関与していただきたいということを願っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"阿部委員","kind":"質問・要望","question":"そうなってくると、今、これは予定地というのはいつごろアナウンスできることなのかということを教えてほしいと求めました。７０名定員ということはそれなりに広いものなんだろうと思うんですけれども、２階建てなのか、もし今の形で言えるものがあれば教えていただきたい。","respondent":"立川保育課長","answer":"１２月より、大崎三丁目に移転する予定である旨、このように考えております。１階、２階を保育室として、３階に事務スペースを設けるというように聞いております。","id":"exchange-025"},{"speaker":"南委員","kind":"質問","question":"だから、平成２６年度オープンですから、そのときは大崎三丁目で紹介をするということになるんですよね。それこそ近くのところでどうこうできるのであれば、そうではないので、その辺が心配になってしまっているんです。","respondent":"立川保育課長","answer":"１歳児と２歳児につきましては、３歳以降、転園等を想定された形で対応するのは０歳児。１歳までは現在のところ、２歳になったときに大崎に行くということで、保育園から丁寧に説明を行っていくということになります。","id":"exchange-026"},{"speaker":"南委員","kind":"質問・要望","question":"通園・通勤も含めて、できないわという保護者がいた場合には、区の対応というのはどういうふうになるんですか。その辺の心配のそういうことはどういうふうに考えているのか、最近は私たちもあまりないもので、教えていただきたい。","respondent":"立川保育課長","answer":"これは移転ということなので、それぞれ個別に保護者の方に説明するかどうかということにつきましては考えてはおりません。","id":"exchange-027"},{"speaker":"南委員","kind":"質問・要望","question":"そこについてはこれからの検討となるんでしょうか。今回、このときでは要望にとどめておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"阿部委員","kind":"質問","question":"先ほど出ました私立保育園、認可保育園の移転に際して、これは大崎三丁目の土地を取得すると結構コスト的にもかかると思うんですが、一方で助成等々も出やすかったかなと思うので、お金をどのような形で、今年は大丈夫とか、その辺の仕組みだけ教えていただけますか。","respondent":"立川保育課長","answer":"現在、聞くところによりますと、土地を取得してということではなくて、賃貸借をするというふうに聞いております。移転に関する助成に対しましては、経理的なところですけれども、現在ですと、国と都の補助等を利用して移転することができるということです。","id":"exchange-029"},{"speaker":"阿部委員","kind":"質問","question":"要は賃貸借で土地なり、プラス建物なりの賃貸借をして、かつ、国の補助金なり、安心こども基金などが活用できるのか尋ねました。","respondent":"伊崎待機児童対策担当課長","answer":"既存保育園の移転につきましては、定員拡大と地域で抱える待機児解消に寄与するということであれば、国の補助金は安心こども基金により、来年度までの予算要求ができるです。","id":"exchange-030"},{"speaker":"渡部副委員長","kind":"質問","question":"いわゆる転入希望というんですか、転園というんですか、そういう形でそういう世代を受け入れていくのか。あくまでもこれは移転ですから、１年間、何年間かは大崎三丁目の保育を受けられるわという形の方もいらっしゃるかもしれませんよね。","respondent":"立川保育課長","answer":"移転ですので、現在在園している子どもにつきましてはそのまま受け入れということになります。移転後に４歳、５歳児のあきが出てくるということにつきましては、子どもが持ち上がってくるまでは定員にゆとりがあるです。","id":"exchange-031"}]},{"id":"topic-04","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"昭和通りおばちゃんちはオープンして１カ月、品川宿おばちゃんちのほうは、契約保育というのですか。１日は一時預かりのほうで対応するんだろうけれども、どんな状況かなということを知りたいので、そのあたりを教えてほしいと求めました。","respondent":"伊崎待機児童対策担当課長","answer":"月極で短時間就労などを使う方について、席を確保しておくという意味合いから１カ月の契約という形をとっていただいているところです。今年度につきましても、契約保育は毎月三、四名程度のご利用者があります。","id":"exchange-032"},{"speaker":"南委員","kind":"意見","question":"毎月三、四名というんだけれども、例えば４月に入って１年近くとか、あるいは次の年の３月までとかという状況があるのかどうかを聞いたんですけれどもとの意見を述べました。","respondent":"伊崎待機児童対策担当課長","answer":"昨年の４月に保育園が開設したという関係もございまして、昨年はあまり年度当初の契約保育でのご利用は少なかったと聞いております。途中で保育園に入られたり、あるいは途中から使われたりとかという部分等で、人の動きはさまざまです。","id":"exchange-033"},{"speaker":"南委員","kind":"質問","question":"何年も続いているような状況なので、そういう意味では、そういう補完的な位置づけでの利用というのはないと見ていいんですか。それとも、途中で就園しているということだから、一定の期間はあるのかなと理解するんだけれども、その辺はどんな感じか尋ねました。","respondent":"伊崎待機児童対策担当課長","answer":"就労が短い方とか、あと単発的な就労の方というご利用を、そちらの方たちにご利用いただきたいというところを目的として開設しております。ここ近年、保育園の開設も進めておりますので、そういったご利用は開設当初よりは減っていると聞いております。","id":"exchange-034"},{"speaker":"伊藤委員","kind":"確認","question":"何が言いたいかというと、このＮＰＯ法人が何らかの解散、可能性としてはありますよね。この事業が、例えば２０年も安定してやっていけるような気も、そういう契約はどういうふうになっているかということを確認します。","respondent":"伊崎待機児童対策担当課長","answer":"といいながらも、当然、開設のときは事業の継続性がある程度担保されるという実施主体者への確認はいたしてからやっております。今回も財政状況等々をすべて勘案しまして、２カ所目のオープンを認めたです。","id":"exchange-035"},{"speaker":"伊藤委員","kind":"質問","question":"もちろん頑張ってほしいし、続けてほしいことは前提なんだけれども、３０年続くとは思わないわけです。あるいはまた別な法人に移行していくなり、そういうようなことを行政として考えていく必要があるのではないでしょうかということをお伺いします。","respondent":"伊崎待機児童対策担当課長","answer":"３０年というスパンで見ますと、お答えすることは非常に難しいところですが、利用がある期間は対応していただけるのではないかと考えております。そのとき、そのときの保育サービスの必要度に応じて、区としては対応を考えていきたいと考えています。","id":"exchange-036"},{"speaker":"伊藤委員","kind":"質問","question":"万が一、そういうことも賜った上で対処していってはいかがでしょうかということで、それは当然お願いしたいです。お願いします。","respondent":"伊崎待機児童対策担当課長","answer":"こちらにつきましては３年間の契約ということで更新を前提として契約していただいております。そのときは区も法人任せではなく、実施事業の補助主体として、区民の方々に迷惑がかからないように考えていきたいと考えています。","id":"exchange-037"},{"speaker":"阿部委員","kind":"確認","question":"注目すべき事業だと思っているんですが、ただ、こういうような対策について幾つか確認したいこともあります。運営実績なんですが、この平成２３年度の内容を見ていますけれども、時間で言えば何時間なんか尋ねました。","respondent":"伊崎待機児童対策担当課長","answer":"合計の数字でご説明いたしますと、日数ですが、平成２３年度は２６２日間の保育日数がございました。一時保育につきましては、６,３２３時間の年間の事業時間がございました。","id":"exchange-038"},{"speaker":"阿部委員","kind":"質問","question":"利用者の１時間あたり５００円というのがどのように、そこの数字を整理したいと思ったんですが、すぐ出ないようでしたら自分でやります。今後どういうふうに展開されていくつもりなのか、商店街以外のところではどういう形で展開するのか、そういった今後の考え方についてお聞きします。","respondent":"伊崎待機児童対策担当課長","answer":"子育て支援事業の地域の方々による展開というところもあわせてスタートしたものですので、現在のところでは。２軒目の昭和通りおばちゃんちをやったという経緯もありますので、また当然という話になりましたら、排除するということではございません。","id":"exchange-039"},{"speaker":"阿部委員","kind":"質問","question":"実際はコストが幾らかかっているのですかという質問をしているのであって、１時間の補助は書いてあるのでわかります。その点と、それから基本運営費の積算の考え方について、どのようにお考えでしょうかということをお伺いしたいと思います。","respondent":"伊崎待機児童対策担当課長、金子子ども未来事業部長","answer":"全体の経費ですが、平成２３年度の決算で９００万円余ということになっておりますので、申しわけありません。今、電卓がないものですから、延べ人数または時間数ということで割り返すと、時間単価が出てまいりますので… それから３年間の家賃補助が出る、こういったことを活用して商店街の振興にも役立てていこうというふうなスキームでつくった事業であります。","id":"exchange-040"},{"speaker":"高橋委員","kind":"質問・要望","question":"大変興味深い取り組みなので続けていっていただきたいんですが、こういうことが載っているので、どこかにつないでくれているんでしょうか。そういう例がもし、今、おわかりでしたら。","respondent":"伊崎待機児童対策担当課長","answer":"こちらは保育園と同じで健康なお子さんですので、病気の最中の病児保育としてのご利用はできない状況です。特別な支援、相談をしていただいて、受けていただいているです。","id":"exchange-041"},{"speaker":"高橋委員","kind":"質問・要望","question":"区でそういった病気等で、他機関へつなげることが多いと思うので、その辺はまた確保していただけるとありがたいと思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"阿部委員","kind":"質問","question":"これは直接契約ではありますけれども、できるだけ区民をみたいなお願いといいますか、各園に対してはそういうことはされているんですか。本来であれば、それぞれの区内でというのが一番理屈が通るのかなと思うんですが、その辺はどのようにされているんか尋ねました。","respondent":"伊崎待機児童対策担当課長","answer":"地域開設につきましては、できるだけ区民の方をというお話はしております。ただ、直接契約ですので、最終的に契約をしますのはその施設の母体の事業者ということになってあります。","id":"exchange-043"},{"speaker":"阿部委員","kind":"質問","question":"今日伺ったところも既にウエイティングが出ているような話だったと思うんですけれども、恣意的にといいますか、任意で入園者を選ぶことができる仕組みということで理解していてよろしいんか尋ねました。","respondent":"伊崎待機児童対策担当課長","answer":"東京都の認証保育所の実施要綱で定められているものにつきましては、特に入所の規定はございません。ですので、事業所によって、その選考に基準が違うというところです。","id":"exchange-044"},{"speaker":"阿部委員","kind":"質問","question":"幼稚園等々は３歳、４歳ぐらいから実施するというところで、そこは丁度うまくいっているような調整とかはされているんですか。変な質問で、わかりにくい質問で申しわけありません。","respondent":"立川保育課長","answer":"その変更については、現在のところ、対応ができていると認識しているところです。３歳からは私立の幼稚園という方もある一定いらっしゃいますので、これまでもそういう流れでやっているところです。","id":"exchange-045"},{"speaker":"阿部委員","kind":"意見","question":"この年代がきついという予測が立っているとか、そこまでは考えていないんだとか、そこら辺の担当課としての準備ぐあいというようなところなんですけれどもとの意見を述べました。","respondent":"伊崎待機児童対策担当課長","answer":"今申し上げた２点につきましては、そこに一定出てきて、一定の結果をもとに再度組み立てをしていく必要があるんだろうと。４歳、そういった見通しを持って進めておりますが、今後調査の結果でまた大きくこのあたりは変更することにはなると考えております。","id":"exchange-046"},{"speaker":"南委員","kind":"質問・要望","question":"Ａ型はこうで、Ｂ型はこうだということを教えていただきたいのと、ポピンズナーサリースクール東品川はプラス２１名オーバーしていますよね。伺うんですけれども、あるいは、経営主体のところがどういうふうになっているのかを教えてほしいと求めました。","respondent":"立川保育課長、伊崎待機児童対策担当課長","answer":"ポピンズナーサリースクール東品川の定員の、経営主体が、ポピンズナーサリースクール東品川については後ほどお答えいたします。個人の方が２施設、ＮＰＯの施設につきまして２施設… 当然、保育所設置基準に基づきまして、この人数まで受け入れが可能だということで受け入れているところです。","id":"exchange-047"},{"speaker":"阿部委員","kind":"質問","question":"教育委員会からのご報告があるとか、そういうことになるのか、どうなんでしょう。何か、どういう基準を持って選んでいらっしゃるのかということの考え方を含めて教えていただければ。","respondent":"太田指導課長","answer":"今後の対応策とか、当該校の対応については、まとめているところです。新聞の内容につきまして一つ一つご報告というのはなかなか難しいので、そういった機会にまとめてご報告しようと考えています。","id":"exchange-048"},{"speaker":"阿部委員","kind":"意見","question":"こういうときに委員会もあることであるし、そういったご報告もあわせていただけたほうが、逆に違和感がないのかなと思いました。それは私の意見ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-049"},{"speaker":"南委員","kind":"質問・要望","question":"安心もできるしという点で、１月にやるからいいよと考えないで、丁寧に報告というのはしていただいたほうがいいと私は思うんです。そういう状況って、いつの時点でどういうふうになっているかってわからないところなので、そこを報告してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"伊藤委員","kind":"質問・要望","question":"しっかりと調査報告をまとめた上で、的確であることを確認した上で、しかも効率的な方法をあわせた上で議会に提出したほうが私はいいと思います。やはりしっかりとしたものを求めていって、それは私の意見で、そのように話をします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"渡部副委員長","kind":"質問・要望","question":"今、その議論をする場ではございませんで、１月、２月、これからの委員会で、昨日お話ししたことがありますので、それで進めさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"阿部委員","kind":"質問・要望","question":"事件の事実関係についての調査とか、そういったことを今、求めているのではないんです。多分、教育委員会の方も重々ご理解いただけると思いますので、意見として受けとめてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/162678?Template=document&Id=4778#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":37948,"voices":141}},{"id":"h24-20121127-5","meetingId":"h24-cm11","date":"2012年11月27日","dateIso":"2012-11-27","committee":"総務委員会","time":"午前１０時００分～午後０時００分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を28件整理しています。","topics":[{"id":"topic-01","title":"はじめに(1)の「新地方公会計制度に基づく財務４表」","agenda":"はじめに(1)の「新地方公会計制度に基づく財務４表」","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"この表を見てわからないところがあったので二点ばかりお伺いしたいのですが、私立保育所５億円、実際と見て。再開発４０億と小さい字で書いてあるのですけれども、さっきの質問でそう判断するのですが、もうちょっと中身を教えていただきたいのが１つです。","respondent":"本城企画財政課長","answer":"１番はちょっとさっきのご説明と重なりますが、今回で言えば、１２月２１日号でわかりやすい形でＰＲします。全部で３,０００部ほど、昨年で言えばつくっておりますが、ほかのわかりやすい情報も加えながらご説明をさせていただいているところです。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問","question":"一つは別紙３のところで、再開発４０億円と、この辺がこの団体への補助ですか。その辺が１つと、連結のところの区内の公社とか協会とかこの辺の案分とかはあるのかどうか、そこを説明するよう求めました。","respondent":"本城企画財政課長","answer":"ちなみに、行政コスト計算書、これは平成２２年度版なのですが、福祉という項目の中では、およそ５２.３％ほどのコストがかけられているです。連結の関係で、品川区のみが出資しているものについては１００％、この中に計算されて連結されているという関係です。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問","question":"ちょっとその位置づけが、ここに入るというところが何でかなという疑問があったので、そこを一つ続きでお伺いしたいのが１点です。東京都２３区の状況をそれぞれ見て、そういう部分も含まれているのかどうか、どこをどう見たらいいのかというところも説明を求めました。","respondent":"本城企画財政課長","answer":"ちょっとご説明不足だったかもしれませんが、これは予算と分けるときに目的別の分け方と、性質別の分け方というのがあります。今、指標だとか使いながら少しご説明させていただきましたが、これからの参考等にすることができるというような位置づけになっているものです。","id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問","question":"この表から読み取ることができるのかというあたりを一点お伺いしたいのと、パンフレット３,０００部ですか、いかがか尋ねました。","respondent":"本城企画財政課長","answer":"２３区等、今ご説明させていただいた範囲で申しますと、負担率が１０４.８％ということでご説明させていただきましたが。個別的な説明とかは、発行に対する問い合わせ先として、こういうことも含めて対応ができる体制には一応させていただいているところです。","id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問","question":"質問のお問い合わせとなっていると今、最後にお伺いしたのですが、お問い合わせってあるのでしょうか。できたら、双方向になると、より理解が深まると思うのですが、今のところいかがか尋ねました。","respondent":"本城企画財政課長","answer":"一番多くの区民の方に触れるのが広報等の場面ですが、毎年せいぜい一、二件ぐらいのお問い合わせがありますが、そういう意味でよりわかりやすくする努力はこれから必要だと思いますが、必要に応じての対応はさせていただいていると考えているところではあります。","id":"exchange-005"},{"speaker":"石田（慎）委員","kind":"質問","question":"ちょっとわからなかった二点ほどお伺いしたいですけれども、計算式というのですか、普通会計だと３８億円のものが連結だと２８２億円と膨らんでいる。今まで世代が全部払ってきたというのが１００％で計算して、１０４.８％ということで、ちょっとそこをもう少し詳しく教えていただけると。","respondent":"本城企画財政課長","answer":"その実際の開きということと違うのだという趣旨でご説明させていただいたのですが、ちょっとそのあたり、趣旨まで含めて調べさせていただければ。ちょっと勉強不足で申しわけありません。","id":"exchange-006"},{"speaker":"須貝委員","kind":"質問","question":"お聞きしたいのですが、財務４表の増減額内訳、別紙３ですか。何ですか、そういうものを書いていたほうが、ただ投資というふうに出されてしまうとわかりにくいと思うのですね。","respondent":"本城企画財政課長","answer":"この表だけだと、ちょっとわかりにくいところはそういった形でちょっと補足説明をしながらご理解いただければと考えているところです。","id":"exchange-007"},{"speaker":"須貝委員","kind":"質問","question":"４０年、５０年ということで。３年ごとに資産を見直しているのか、その辺について、もう１回説明を求めました。","respondent":"本城企画財政課長、日下部企画部長","answer":"この資産の評価の仕方ですが、割と資産の評価を厳密にしなくてもできるような形が今回の位置づけです。今ご指摘があった行政財産を含めた資産の評価はそれぞれのスケジュールの中で順次やっていくという位置づけのものがなっているとい… 償却の概念がありませんから、ある意味で企業会計の視点からの整理というと必ずしも十分なものには行き届いていないという問題点がやはりあります。","id":"exchange-008"},{"speaker":"大沢委員","kind":"確認","question":"さっきの別紙２の負担割合のところでちょっとお伺いしたいのですが、１０４という数字がどうしたって出てこなくて、１０３としか出てこない。これ、どういうことなんか尋ねました。","respondent":"本城企画財政課長","answer":"１０４.８ということで、純資産の額が９,２７８億円でございまして、それ割ることの公共資産であります８,８４９億８,０００万円。それを割るということで。","id":"exchange-009"},{"speaker":"鈴木（真）委員","kind":"確認","question":"１カ所ちょっと確認なのですが、経常収益を入れると、それに分担金とかを入れて載せているのですよね。こっちは去年の表だと、分担金を載せてしまうと１０２億円ぐらいになるのですけれども、何で変えたのかなというのをちょっと確認したいのですが。","respondent":"本城企画財政課長","answer":"別紙３のほうをちょっとご覧になっていただきますと、経常収益のところで６８億と。先ほど、ちょっと省略してしまって申しわけありません。","id":"exchange-010"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"確認、これ何なのというのはやっぱり言われることがあります。ですから、相当な理解ができると思いますし、我々議員の中でもしっかり勉強していかなければいけないというのは常に感じているところです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"}]},{"id":"topic-02","title":"の「第２０回品川区世論調査について」","agenda":"の「第２０回品川区世論調査について」","exchanges":[{"speaker":"石田（慎）委員","kind":"確認","question":"９ページの健康についてのところで、よりよいものができるのかなという思い、ちょっとどのような委託状況なのかなと思ったので確認しました。そのデータを全部回収するだとか、条件というか、やられているのかというのがもしわかれば示すよう求めました。","respondent":"荒井広報広聴課長","answer":"それにつきましては、データは廃棄をするか戻してもらうか、いずれかの規約になっているというふうに記憶しています。それから、設問についてのご要望につきましては、今後の参考にします。","id":"exchange-012"},{"speaker":"阿久津委員","kind":"質問","question":"ご説明、ありがとうございました。今、お聞きしようかどうかを迷っていたのですが、ちょっと参考までにここ３回ぐらいまでの定住意向の何％だったというのをまず教えていただけますか。","respondent":"荒井広報広聴課長","answer":"１８回ですから、これは平成２０年に実施したときは８８.９％です。それから、１９回ですが、１９回のときは８９.７％です。","id":"exchange-013"},{"speaker":"阿久津委員","kind":"意見","question":"これも非常に違いがある、非常にという違いかどうかあれなのですけれども、品川区の場合はずっと住みたい５３.８％とここに書いてあるとおり。子育てが終了したら、一丁目一番地でこの９１.５％、そこら辺の比較の仕方等もまた考えていってほしいと求めました。","respondent":"荒井広報広聴課長","answer":"本書の報告書の中でライフステージ別であるとか、それから継続して住まわれている方とのクロス集計などがありますので、それでさらに定住意向というのが詳しく見られるかなと考えているところです。","id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問","question":"お伺いしたいのが一点と、やはり、ここに答えてくださる方というのはかなり関心が高まる傾向にあると思うのですね。担当課の思いも入らなくてはいけないし、その辺の結果をまとめた後の活用の仕方とか、その辺がどういうふうにされているか説明を求めました。","respondent":"荒井広報広聴課長","answer":"２３区、ほかのところを拝見いたしましても、江東区が７５.３％ということで、同じように個別面接法を実施したところは高くなっております。ご説明させていただいたところと、隔回実施とか、実施しています。","id":"exchange-015"},{"speaker":"飯沼委員","kind":"意見","question":"１つだけ、今後充実すべき防災対策のところで自助・共助、項目ってここに載っているのはそのままなのですよね。せっかくのこういう聞くチャンスなので、この辺はもうちょっと細かくてもよかったのかなと感じたので、それは意見なのですけれどもとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"須貝委員","kind":"質問","question":"中堅の人はどうなのだ、ご高齢者の人はどうなのだ、そういうのがちょっとわかるのかなと。前も何かそのような質問、また、何かご検討とかしたのか尋ねました。","respondent":"荒井広報広聴課長","answer":"年代別についての集計の件なのですけれども、あらましのほうにはあくまでも単純集計ということでご理解いただいて、あと、報告書のほうに、間もなくでき上がるのですけれども、そちらのほうに年代別等がありますので、ご覧いただくという形でご理解ください。","id":"exchange-017"},{"speaker":"鈴木（真）委員","kind":"確認","question":"項目的に確認したいので、表紙の中で調査の内容の項目なのですけれども、これは毎回同じなのでしたっけ。ちょっと前回のを調べてこなかったので、大体が同じふうなことだと捉えていいのか尋ねました。","respondent":"荒井広報広聴課長","answer":"上から１、２と、それから１０につきましては継続的に調査しておりますので、同じ項目です。何回かに１度とか、前の長期基本計画の時以来とか、そういうような形で設定しています。","id":"exchange-018"},{"speaker":"鈴木（真）委員","kind":"意見","question":"これは全体的には商店街というか、商店街だったら商店街がやるべき部分かなという思いで。区がやる部分かなと思うけれど、ちょっと限定がついているような気がしたのですが、その辺どうかなと思いますとの意見を述べました。","respondent":"荒井広報広聴課長","answer":"それから商店街調査というのを区商連と地域振興事業部の商業・観光課と一緒に実施したところなのですが、皆さん方が商店街に対してどういうイメージを持っているかということを調査いたしまして、両方を比較するというようなことも考えているところです。","id":"exchange-019"},{"speaker":"鈴木（真）委員","kind":"意見","question":"中身がいい悪いではなくて、何か気になっているところが一点。それから逆に今回選ばなかったのかもしれないけれども、教育関係というのは、今まで、前回なんか、教育に関してはありましたかとの意見を述べました。","respondent":"荒井広報広聴課長","answer":"教育に関する項目というのはあまりとらない傾向があります。どちらかというと、子育て環境ということでとらせていただくことが多くなっているというふうに記憶しております。","id":"exchange-020"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"そこら辺が区としてどう、その辺抜きでいいのかというのがちょっと感じたところです。２番の生活環境については評価できる部分ですとか、これに区としてどこかに出していただいて、施策に活かしていただきたいということを要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"}]},{"id":"topic-03","title":"の「平成２４年１２月１６日執行 東京都知事選挙執行要領および衆議院議員選挙・最高裁判所裁判官国民審査について」","agenda":"の「平成２４年１２月１６日執行 東京都知事選挙執行要領および衆議院議員選挙・最高裁判所裁判官国民審査について」","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"ここに配布期限が１２月１４日（金）までとなっていて、期日前の投票に行くときに公報が届いていない場合がありますよね。区役所とあと地域センターの投票所のところで十分その辺が見られるのかどうかという質問なんかも受けたので、ちょっとそこのところをお伺いします。","respondent":"諸岡選挙管理委員会事務局長","answer":"非常に混乱が起きるので、むしろちょっとおくれたのが、そのほうが混乱は少ないのかなという感じはしております。庁舎、それから地域センターにも早目に配布してどこでも見られるようには十分に留意させていただきたいと思っています。","id":"exchange-022"},{"speaker":"飯沼委員","kind":"質問・要望","question":"投票のやりやすさというか、清き１票なので、現行の期日前とか不在者のところの改善を求める声もあるのですね。坂を下っていったり上ったりしないと、投票所に行かれないという方に対して何か改善策はないかと思っているのですが、いかがか尋ねました。","respondent":"諸岡選挙管理委員会事務局長","answer":"やっぱり利便性の多いところに集中をしたりというか、非常に混乱があるということで、なかなか難しいところだと思います。機械的には可能であるかどうかといわれれば、それは地域変更もできるわけですので、これはもう少し慎重にリサーチさせていただきたいと考えています。","id":"exchange-023"},{"speaker":"飯沼委員","kind":"質問・要望","question":"あるとは思うのですが、ぜひその辺を前に進みますように考慮していただきたいと思っています。やっぱり不便で何とかしてほしいという部分も受けとめるというか、実際にどういう状況なのかというのも調べていただいて、いかがか尋ねました。","respondent":"諸岡選挙管理委員会事務局長","answer":"そちらでも不在者投票ができるような制度もありますので、そちらのほうもご活用いただければと考えています。かなり増えてきておりますので、そちらのご活用もお勧めいただければと考えています。","id":"exchange-024"},{"speaker":"飯沼委員","kind":"質問・要望","question":"その制度からはみ出ている部分で、やはり投票をしたいのにできない、ぜひ検討の中に入れてほしいと求めました。別問題ではないですよ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ということで、ざわざわしないでいただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"鈴木（真）委員","kind":"確認","question":"投票所が変わるということで、これは地域の方はやっぱり今まで行っていると、どうしても前回と一緒だと思ってしまう。そこら辺の確認をちょっと。","respondent":"諸岡選挙管理委員会事務局長","answer":"特に浅間台小学校から特別支援学校、その点は十分に配慮する必要があるだろうと思っておりまして、もちろん委員がおっしゃいましたように広報ですね。","id":"exchange-027"},{"speaker":"鈴木（真）委員","kind":"意見","question":"あそこはちょうど坂の途中で、坂を下りてしまってまた上ってくるとか。そこに行ってしまえばわかるのだろうけれども、その辺も、やっぱり地域の人に聞かれるので、その辺ぜひ対応との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-028"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/579213?Template=document&Id=1932#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":39346,"voices":85}},{"id":"h24-20121128-14","meetingId":"h24-cm11","date":"2012年11月28日","dateIso":"2012-11-28","committee":"行財政改革特別委員会","time":"午前１０時００分～午前１１時３０分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を23件整理しています。","topics":[{"id":"topic-01","title":"旧西五反田職員待機寮跡地の売却","agenda":"旧西五反田職員待機寮跡地の売却","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"住民要望を大事にして、介護施設の住宅支援や区営住宅など、そういった住宅施設に充てるべきだと思います。ちょっと伺いたいんですけれども、そこを伺いたいと思うのと、どういう関係になるのかを２つ目に伺いたいと思います。","respondent":"平澤経理課長","answer":"地方自治法施行令第１６７条の第４項第１号に該当する者は参加できないということで、いわゆる禁治産者等、そういうのは参加できません。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問","question":"それとも既存のまま改修して使うのか、それとも補強して使うのか、そういうところは相手方が決めるということになるのでしょうか。そこだけ伺いたいです。","respondent":"平澤経理課長","answer":"所有権が移転されますと、それは先方のご判断ということになると思います。","id":"exchange-002"},{"speaker":"須藤委員","kind":"質問・要望","question":"区民要望に沿って、こういう寮を売却したというのはいい結果で、議会でも寮を減らす方向で進めていたので、そういうふうになったと思う。３億４２０万円というこの金額を入金させて、単に一般収入として使っていってしまうのか、そのあたりの考えはどうか尋ねました。","respondent":"日下部企画部長","answer":"基本的な考え方は、私どもの今までの考え方では、公共施設の整備基金の原資として活用していくということが基本です。ケース・バイ・ケースということもありますけれども、基本的にはそのような考え方に立っております。","id":"exchange-003"},{"speaker":"須藤委員","kind":"質問","question":"せっかく有効活用という意味できているので、それが見えなくなるのではなくて、こういうふうに活用されていますというのを、我々が区民に説明できるような仕組みをつくってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"西本委員","kind":"意見","question":"入札申し込み者が８社で、参加者が４社、この４社の方の辞退はどういうふうになっているかとの意見を述べました。","respondent":"平澤経理課長","answer":"こちらにつきましては、売却なので、工事とかそういう入札ではございませんで、売却ということで、買い取りのことですので、何らかの会社のご事情もあったということで、その辺は承知してございません。","id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"２位ぐらいの金額は教えていただきたいのと、この３億４２０万円は、２位との方と。３億４２０万円で、思ったより１億円以上多かったとしたら、もしかしたら考えるのかということもあわせて説明を求めました。","respondent":"平澤経理課長、日下部企画部長","answer":"予定価格の１億８,０００万円との乖離ですが、予定価格につきましては、それに基づいて決定させていただいるところです。この予定価格につきましては、または上物の処分の価格を入れまして、正当なものだと現在も考えているところです。 売却益の活用ですけれども、確かに当初の見込み以上の金額が入ることになるわけです。基金を活用するということになりますので、これを切り分けるということは、基本的には今のところは考えておりません。","id":"exchange-006"},{"speaker":"石田（秀）委員","kind":"意見","question":"そういう状態の中でも、この時期になってくるともう、ちょっと陰りが出てきている。でしたら、やっぱり時機をしっかりとらえていくことも考えていくべきだと思うので、それだけはとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"}]},{"id":"topic-02","title":"の２、特定事件調査","agenda":"の２、特定事件調査","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"その上で伺いたいんですけれども、１番にあります旧原小学校は、いわゆる今でいうパブリックコメントは行っていません。どういう判断があるのか、一つ一つ住民参加を位置づける姿勢が必要ではないかと思うんですけれども、ここを伺いたいと思います。","respondent":"柏原行財政改革担当課長","answer":"平成１８年６月の終わりから８月１５日まで１月半以上、制度はなかったんですが、先駆け的なことは行ったということは言えるかと思います。例えば、利用計画が案としてできあがったところで、広くご意見をいただくといった流れでやってきているところです。","id":"exchange-008"},{"speaker":"中塚委員","kind":"質問・要望","question":"本格的にこうしていきましょうとなった時点では、パブリックコメントをかけるということでよいのか、改めて伺いたいと思います。恒久的にやっていくと言いながら、なぜここはかけてこなかったのか、その理由をご説明ほしいと求めました。","respondent":"柏原行財政改革担当課長","answer":"例えば、そういった計画が出てきた流れの中では、パブリックコメントという手法をとることにはなるだろうとは考えてあります。まだ設計をしている段階ですので、こちらにつきましては、まだそういった形でご意見を聞くタイミングではないと考えています。","id":"exchange-009"},{"speaker":"中塚委員","kind":"質問・要望","question":"伺いたいのは、案をつくる段階では意見はいろいろ伺っているんだと説明しますけれども、この間かたくなに拒んでいるんです。地域住民の事業説明会をかたくなに拒む、その姿勢を改善していく必要があるのではないかと思うんですけれども、その考えを伺いたいと思います。","respondent":"柏原行財政改革担当課長","answer":"今までの地元の方への説明ということですが、動きが少し変わったという部分もございましたので、改めてさせていただいたところがあります。町会の関係の方、地元の方の意見調整や説明会やお話し合いというのは、一概に説明会をやっていないということではないかと考えています。","id":"exchange-010"},{"speaker":"中塚委員","kind":"質問・要望","question":"さまざまな要望が挙がるわけですけれども、引き続き長くその地域にあり続ける施設ですから、そこを位置づけるべきだと。ぜひそこをやっていただきたいし、そういう仕組みづくりそのものも、この際しっかりつくるべきだと思うんですけれども、改めていかがか尋ねました。","respondent":"日下部企画部長","answer":"しっかりとした議論を前へ進めていくためには、１つは、基本的な考え方をまず整理するということが大事だと思います。ですから、私どもは何もすべてがすべて拒んでいるわけではありませんで、それは適宜対応しているということでご理解をいただきたいと思います。","id":"exchange-011"},{"speaker":"中塚委員","kind":"質問・要望","question":"今パブリックコメントという形でそこをやってはいるけれども、どういう計画なのか直接説明を聞く場がないという話をよく伺うんです。意見を直接言う、説明することを聞く場を設けていく、そういう仕組みが必要ではないかと思うんですけれども、最後の部分を改めて伺いたいと思います。","respondent":"日下部企画部長","answer":"高齢化に対応する形で、区と自治会連合会が本当に一緒に協力して、いろいろな検討をしてきた経緯があります。これが一番いいと考えていますので、その時々の状況に応じて、柔軟に対応していきたいと考えています。","id":"exchange-012"},{"speaker":"須藤委員","kind":"質問","question":"こみゅにてぃぷらざ八潮の使用率はどのぐらいに上がってきているんか尋ねました。","respondent":"日下部企画部長","answer":"ただ、それにしてもほかの文化センターなどの水準に比べれば、ちょっと低目であると。例えば、そういうところはかなり人気がありまして、普通の会議室なんかよりも利用実績は上がってきているということで報告を受けております。","id":"exchange-013"},{"speaker":"須藤委員","kind":"質問・要望","question":"こういう形になるので、区民の皆さんとそれをどうやって活用して生かしていくんだという話し合いを進めていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"塚本委員","kind":"質問","question":"それから、老人保健施設ということも１つ必要、ということは、区の行政と、議会としても共通のコンセンサスなのかと思います。どう利用しようかというところでの重点的な視点、プライオリティー、そういったものをちょっとお伺いしたいと思います。","respondent":"日下部企画部長","answer":"これはもう高齢化が急速にどんどん進行していきますので、それにすべて、施設面でどれだけ対応していったらいいのかというのは難しいんですけれども。私どもとしましても、高齢者への対応、それから防災関係、この辺が今特に重要な課題だということで、同じ考え方です。","id":"exchange-015"},{"speaker":"塚本委員","kind":"質問","question":"わかりました。品川区にもどうやらそういうのが８施設あって、今どのようなお考えをお持ちになっているか、ちょっとお伺いしたい。","respondent":"柏原行財政改革担当課長","answer":"１１月２６日、１年前に出たもののリニューアル版といいますか、品川区内でも８施設該当です。先ほども地元の声とかいろいろお話がありますので、そういったところを踏まえながら、多角的な検討をしなければいけないという考え方です。","id":"exchange-016"},{"speaker":"塚本委員","kind":"意見","question":"わかりました。先ほどの行政需要をどういうプライオリティーでというところも含めて、よろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"石田（秀）委員","kind":"提案","question":"１００％あるようなことを言っておけば、１０人に意見を聞いたら、１０人中１０人要望は言うと思う。私も何回かお話は伺ったし、それまで許して勉強会までやって、そんなことをしてああいうことになったとの意見を述べました。","respondent":"日下部企画部長","answer":"私もちょっとかかわった経過を考えますと、もっと有効活用を図るために、もう少しフレキシブルに運用していくというのも１つ考えなければいけない。","id":"exchange-018"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"その機能は、これから高齢者が増えてくるから、そうしましょうといってやってきたわけじゃないですか。そういう部分の模索をぜひしていただきたいと、要望にしておきますけれども、ぜひないようにしていただきたい。","respondent":"日下部企画部長","answer":"その辺は常にチェックするような形をとっておりまして、今ご指摘のようなケースというのは、ほかにはまずございません。今の現状ではなかなか困るので、もうちょっと広いところをとかという話が来ることが大半ですので、ほかにそのようなケースはないと考えています。","id":"exchange-019"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"あそこは高齢者が結構増えてきているけれども、逆に、高齢者住宅にかえてくれと。５,０００世帯、私はどこかで考えていただきたいなと、それだけ言っておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"西本委員","kind":"質問・要望","question":"要望だけではなくて、一緒にやっていこうということを、もう一つ運営の主体というのがあると思うんです。住民の意識改革というんですか、どういう形で、そこら辺はどうなんか尋ねました。","respondent":"日下部企画部長","answer":"その当時自治会の各会長方が結構中心になってご検討いただいた経緯もありますし、自治会ですから、結構会長がかわるケースというのが多いんです。地域のいろいろなご要望とか、ご意見をある程度、その辺は受けとめた形で運営ができているのではないかと考えております。","id":"exchange-021"},{"speaker":"西本委員","kind":"質問","question":"それは１つの発信としていいんでしょうけれども、反対するのだったら、反対するなりの代案を必ず出してもらうべきだと思うんです。あんまり時間をかける必要はないと思うので、そこの見きわめもそうだと思うし、これからの協働についての考え方だけ説明を求めました。","respondent":"日下部企画部長","answer":"協働という言葉は１つですけれども、適切な進め方をしていくことが大事ですし、フレキシブルにいろいろなことに対応していくと。協働ということについても、そのようなことが言えるのではないかと考えております。","id":"exchange-022"},{"speaker":"中塚委員","kind":"質問・要望","question":"この行財政改革委員会に前かけられた四中跡地の請願なんですけれども、今日はご報告してくださいとは言いませんけれども、要するに、その後どういう状況なのか、どんなふうになっているのか、次回以降でも、若干の経過説明があればと思いますので、ご検討ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/931720?Template=document&Id=5936#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":29985,"voices":56}},{"id":"h24-20121129-17","meetingId":"h24-cm11","date":"2012年11月29日","dateIso":"2012-11-29","committee":"震災対策特別委員会","time":"午前１０時００分～午後２時５７分","status":"正式会議録","sourceType":"formal","overview":"震災対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を66件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"武内委員","kind":"質問・要望","question":"これに伴って、学校避難所マニュアルのほうで何か反映されるようなものというのがありましたら、教えていただきたいんですけれども。学校避難所マニュアルを改訂していくという方向性とあわせて。","respondent":"高山防災計画担当課長","answer":"後ほどご説明いたしますが、いわゆる弱者への対応の部分について、そういった部分については強化してまいりたいと考えております。ペットの関係も、もう少し議論が活発化するような形で、こういったものの標準化のようなものを図ってまいりたいと考えております。","id":"exchange-001"},{"speaker":"武内委員","kind":"質問","question":"水ですか。そこら辺はどんなことか、説明を求めました。","respondent":"高山防災計画担当課長","answer":"一時的に利用する施設でもありますので、その辺のところはよりどういった優先順位といいますか、使用の順位をあらかじめ定めておくのかといったようなことについては記載しておくことがより丁寧かと考えております。","id":"exchange-002"},{"speaker":"武内委員","kind":"質問・要望","question":"これは要望で結構です。５ページですか、各地区に１カ所ずつぐらいあるという認識なんですけれども、その辺はどう考えていらっしゃるのかなと。","respondent":"高山防災計画担当課長","answer":"地域で継続して医療を続けることができる医院については、しかるべき医療機関に早期につないでいくといった形での対応が中心になろうかと思います。その範囲で対応できるものについては、各校において対応いただくことになろうかと思いますが、軽傷などの場合につきましては。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それと、学校避難所マニュアルは学校ごとにできているということなんですが、すべての学校でこれができているんでしょうか。この避難所マニュアルの５ページのところの、１校当たり何人くらいになるのかということと、そこら辺のところを説明するよう求めました。","respondent":"鈴木防災課長","answer":"ここは状況によって交通機関の寸断等もあって、必ず指定した職員が来るとは限りませんので、おおむね１０名ぐらいを指定しております。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"３・１１以後、３・１１以後、教えてほしいと求めました。これも改修を年間５校ずつですか、今後どういうふうに改修をされていく予定なのか、お聞かせほしいと求めました。","respondent":"鈴木防災課長、齋藤庶務課長、武藤河川下水道課長","answer":"区で以前から整備していますマンホール設置型のトイレの使い方をもう一回確認しようとか、そういうようなお話が出ているのを聞いております。それから… おおむね１０校ずつ実施しておりまして、平成２３年度からです。おおむね５カ年で完了の予定ですが、できるように頑張りたいと考えていますけれども… 一応、来年度で避難所等、二次避難所を含む下水道管の耐震化が完了する予定です。","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そこが１つお聞かせいただきたいのと、５年間でということなんですけれども、そのことも教えてほしいと求めました。お聞かせいただきたいのと、少なくとも１階はすべて使えるとか、そこら辺の考え方はどうなっているのかもお聞かせほしいと求めました。","respondent":"鈴木防災課長、武藤河川下水道課長、齋藤庶務課長","answer":"それから区の学校施設で耐震化をしている部分に関しては、基本的には下水、排水のほうの対応です。もう１つはプール、今、対応しています。 一応、さまざまな可能性も考慮しまして、シルバーセンター等につきましても耐震化の工事をしております。 ３つ、男女とも１カ所、あるいはプールの水で使うというような考えでおります。あくまで排水管の耐震化ですので、ご理解ください。","id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そういう中で、トイレというのは何人に１カ所は整備していこうみたいな、そういうふうなものというのはないんでしょうか。それがすごく阪神・淡路大震災のときにもかなり大変な状況だったということが出ていましたので、いかがか尋ねました。","respondent":"鈴木防災課長","answer":"複数のものを使って対応するというのが基本的な考え方で、今、経費や現実的なスペースの問題で難しいかとは考えております。なお、一応、それでも足りない場合には屋外のマンホールに設置するマンホールトイレというような複数のもので対応するというのが現在の考え方です。","id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１カ月で復旧して、一応、そこら辺の見通しというのがどうなっていくのかをお聞かせほしいと求めました。何カ月も避難所生活をせざるを得ないという状況があったと思うんですけれども、そこら辺のところがどうなっていくのかを説明するよう求めました。","respondent":"鈴木防災課長","answer":"閉鎖、もしくは複数の避難所を１カ所に集めて数を減らしていくとか、そういう対応をすることになると思います。状況に応じて、できるだけ避難者の方の少しでも日常に近い健全な生活を維持できるような対応をするというのが計画の考え方になっております。","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"仮設住宅をどう確保していくのか、そこのところが結局、そこら辺のところを１つ教えてほしいと求めました。２倍に多分、私は２倍になってもとても足りないと思うんですけれども、今後の方向もあわせて説明を求めました。","respondent":"松代防災まちづくり事業部長、高山防災計画担当課長","answer":"まず区内でそういったことに対応するとなると、区内で考えられるのは公共的な施設、そういったものが１つには考えられるだろうと思っています。東京都を中心にそういった中で考える、もしくは近郊で考えるとか… おそらくアルミパックをすることで収容量が倍にできるという、そのような趣旨でご説明させていただいていたことかと思います。","id":"exchange-009"},{"speaker":"井上委員","kind":"質問・要望","question":"教室の割り当ての表示なんですけれども、これはすべての学校にもうできているのかどうかということを１つ確認をさせてほしいと求めました。３つ目は、そこら辺の職責というのはどういうふうになっているのか、説明を求めました。","respondent":"齋藤庶務課長、鈴木防災課長","answer":"品川８カ所、計１３カ所ありますけれども、そこにお手伝いをするということで決まっております。もちろん学校設置者である区長、学校の人間でないとわかりませんので、主体的にかかわっていくです。２点目のファクス、それを活用するということで、特に災害時にファクスをどこかから確保して送信するというものではございません。","id":"exchange-010"},{"speaker":"井上委員","kind":"質問","question":"１００％にするのをどの辺の目標に、お答えいただくのはわからないんですが、１００％にするのをどの辺を目標にしているんか尋ねました。","respondent":"鈴木防災課長","answer":"先ほどマニュアルの概要資料で説明をいたしましたように、その割り振りはきちんとお話し合いをして決めておいてくださいというお願いはしております。ただ、今後は教育委員会とも相談させていただいて、どのような対応をするかということは検討させていただきたいと思います。","id":"exchange-011"},{"speaker":"井上委員","kind":"質問・要望","question":"副校長先生をはじめとして連携をとるということなので、そうしていただきたいと思うんですが、そのことについていかがか尋ねました。","respondent":"齋藤庶務課長","answer":"今、防災課長からご答弁申し上げましたとおり、私どもも防災課と十分協議して、対応させていただきたいと思います。","id":"exchange-012"},{"speaker":"大沢委員","kind":"質問・要望","question":"学校避難所マニュアルの概要の４ページの災害時の対策、共通ルールの(3)のところということで、現状を教えていただきたい。","respondent":"和氣学務課長","answer":"劇物・薬物に関しましては、専用の金庫、保管庫を用意してありまして、施錠して管理しています。そういう理科準備室等については施錠して、通常は誰も入れないような形で管理しています。","id":"exchange-013"},{"speaker":"大沢委員","kind":"質問・要望","question":"副校長が現認のもとにそれを管理されているのか、それとも担当の理科の教員が管理をされているのか、どちらかを教えていただきたい。","respondent":"齋藤庶務課長","answer":"今、大沢委員からご指摘された事項は、監査でも指摘された事項でございまして、私も１５校ぐらい理科室を回ってまいりました。その鍵の管理は理科の教員が実施しておりまして、日々管理をしている、薬品庫の管理につきましては極めて良好な状態にあると考えております。","id":"exchange-014"},{"speaker":"大沢委員","kind":"確認","question":"そうすると、最終管理者は校長が管理をされる、こういうことで、管理者である校長、あるいは副校長が最終的には確認するということの順番でよろしいんか尋ねました。","respondent":"齋藤庶務課長","answer":"委員ご指摘のとおりです。","id":"exchange-015"},{"speaker":"阿久津委員","kind":"質問・要望","question":"学校避難所マニュアルの概要の２ページのところで、それだけではあれなので、紙の名簿も併用されるというご説明があったと思います。夜も眠れない日を過ごすということが昨年非常に記憶に残っているものですから、そこで記入して、そういうところを教えてほしいと求めました。","respondent":"鈴木防災課長","answer":"ＮＴＴの１７１、もしくは重度の医療の対応が必要な方の情報だとか、考えているところです。考え方の１つとしては、１７１を使うのか、わが家の防災ハンドブック等で区民の皆さんにもしっかりとお知らせをしていきたいと考えております。","id":"exchange-016"},{"speaker":"阿久津委員","kind":"質問","question":"そこまで詳しくは教えていただけなかったと確かに覚えているんですけれども、ここら辺の仕組みを私自身ももうちょっと考えてみたいと思います。ペットのことについては、また後ほど地域防災計画のところで伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"どういう体制になるのか、でも、一般の避難所にもそういう方というのはたくさん来ると思うんです。そういう方から、ここら辺のところの対応がどういう体制でされるのかを説明するよう求めました。","respondent":"高山防災計画担当課長","answer":"１つの役割分担の中で、この中に医療関係者を当初からはめ込むといいますか、予定しているものではございません。そういった当初の役割の中で、役割分担を当てはめられた方々が初動期における対応を担っていただく、そのような対応になろうかと思います。","id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"そういう力、地域にある力を使って、そういうスムーズな対応ができるようなところでの避難所のあり方ということもぜひご検討いただけたらと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"大沢委員","kind":"質問","question":"学校事情には詳しい方が多いと思うんですけれども、そこら辺の考え、ＰＴＡに対する考え方というのはどのような考え方を持ってやっていらっしゃるんか尋ねました。","respondent":"高山防災計画担当課長","answer":"拒むものでもございませんし、むしろ、そういったことが進んでいくことが理想とは考えております。ただ、なかなか相手のある話といいますか、ＰＴＡの方々の理解も必要という前提の中から、現在のところはそれほど大きな広がりを持っていないです。","id":"exchange-020"},{"speaker":"大沢委員","kind":"質問・要望","question":"もう１つ、教育委員会の方が来ているといったのでＰＴＡのことを聞いたんですけれども、もう１個、別のほうになってしまっていいですか。この部分に対して、弱者としてどのように捉えていて、今後のトイレ対策について反映されていくのか、基本的な考え方を教えてほしいと求めました。","respondent":"高山防災計画担当課長","answer":"そういう意味では、既に取り組みが進んでいる世田谷区などの事例が先だって紹介されていたことは記憶しています。そういった、いわゆる内部障害者の方に対するトイレ対策というのが必要な点については十分認識していますが、その取り組みとしては。","id":"exchange-021"},{"speaker":"大沢委員","kind":"意見","question":"むしろ、ここのところは内部障害の方が何人区内にいらっしゃるか、まして、各避難所に大体どれぐらいそういう方たちがいるのかという事前の数の把握ということは必要だと思うんですけれども、どのようにそこのところはお考えになっていますかとの意見を述べました。","respondent":"高山防災計画担当課長","answer":"そういった情報をもとに、数の把握、そして対応策の検討ということについては進めてまいりたいと考えております。","id":"exchange-022"},{"speaker":"武内委員","kind":"質問","question":"パウチですか、以前に聞いたことがあるんですけれども、それはありませんか。","respondent":"高山防災計画担当課長","answer":"そういう意味では、薬剤師会との間の医薬品の供給協定の中にはその品目はございませんでしたので、区として、いわゆる卸なり、そういった医療業界からの調達の仕組みは、現在のところはないと記憶しております。","id":"exchange-023"},{"speaker":"武内委員","kind":"意見","question":"かえなきゃいけないから、ストマというか。もう一回、もしなければ、つくってもらいたいとの意見を述べました。","respondent":"鈴木防災課長","answer":"もう一度議事録、それから過去の資料等を確認させていただきまして、確認をした上でお答えさせていただきたいと思います。もしラインがあるのであれば、そういうお願いの働きかけもしていきたいと考えているところですので、確認させていただきたいと思います。","id":"exchange-024"},{"speaker":"武内委員","kind":"確認","question":"たしか人によってかえが合う、合わないがあるらしいんです。そういうものを流通してもらうようなルートをつくる、もしくはつくったという話だったので、また確認していただくよう求めました。","respondent":"野呂瀬環境課長","answer":"障害者福祉課等もいろいろ情報提供をしながら進めていくみたいなことで、どれぐらいの人数がいるのかも含めまして、関連の中で障害者福祉課等と情報提供を求めながら進めていきたいと考えております。","id":"exchange-025"},{"speaker":"井上委員","kind":"質問","question":"学校避難所マニュアルの概要のところで、５番の共通ルールで、日常的な維持管理の取り決めというところに、ごみの処理についての記載がないんです。そういう一部を十分に使えるとか、そういったところも想定をしておく必要があると思うんですが、学校側からはいかがか尋ねました。","respondent":"齋藤庶務課長","answer":"委員のご指摘のところは大変重要なところだと考えていますが、ごみの出方、避難されている方の状況を踏まえて考えなければいけないと思います。","id":"exchange-026"},{"speaker":"井上委員","kind":"質問・要望","question":"そのケース・バイ・ケースでするということであれば、ぜひマニュアルのところにごみの表記も必ず入れてほしいと求めました。柔軟に対応するんだということが、いつもそういうふうな連携がとれることが必要だと思うので、お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"沢田委員","kind":"質問","question":"そのもとに置かれるのかというのは、それともずっとそのまま子どもたちは先生たちのもとにいるのか、その辺はどういうふうになっているんか尋ねました。","respondent":"田村教育次長","answer":"１時間おきに報告してくれということなので、当然、考えられるんです。平常時での対応、先ほど庶務課長が言っていた３期休業、来た方については学校が責任を持って対応するという形の徹底をしているという状況です。","id":"exchange-028"},{"speaker":"沢田委員","kind":"質問","question":"１泊とか、２泊とか、避難所運営会議と学校というのは一体的にやられるんだと。親のところに戻すとか、子どもたちは子どもたちでまとまってそこで避難していられるのか、そういう場合はどういうふうな状況になるんか尋ねました。","respondent":"田村教育次長","answer":"たしか８時か９時くらいにもう宿泊しろと、学校の教職員も全員帰ってはだめよと、教育委員会も泊まるからということで引き渡しをやると。対応するということが原則ですので、だけど、その辺は引き続き徹底して本部と連絡を取り合いながら対応していくという形になると思います。","id":"exchange-029"},{"speaker":"沢田委員","kind":"質問","question":"その辺で、学校との関係がわかりました。校門、校舎の開錠のことで１点お聞きしたいんですけれども、災害が起きたときの何か決まりみたいなものはどういうふうな形になるんか尋ねました。","respondent":"高山防災計画担当課長","answer":"学校避難所に参集する時間外の職員ですが、震度５弱のときに６km圏内の職員が参集することとなります。そのような段階で開錠といいますか、避難所機能が徐々に備わっていくというようなことになろうかと思います。","id":"exchange-030"},{"speaker":"沢田委員","kind":"質問","question":"どういうふうな連絡体制で、どの段階で鍵をあけるのかということを、そういう方たちへの連絡体制というのはどのようになっているんか尋ねました。","respondent":"高山防災計画担当課長","answer":"まず校門をあけて、いわゆる校庭内に人が入れるような状態に段階的になっていく、そんなような形になろうかと思います。","id":"exchange-031"},{"speaker":"沢田委員","kind":"確認","question":"確認したいんですが、避難所連絡会議のメンバーじゃない方で鍵を持っていらっしゃる方はいらっしゃらないということですか。学校の周りにお住まいの方で、町会長以外に近隣で持たれている方もいらっしゃると思ったんですけれども、そういうことはないんか尋ねました。","respondent":"高山防災計画担当課長","answer":"基本的にはその避難所を利用する町会の町会長、つまり避難所連絡会議の議長、もしくは防災区民組織の本部長になっております。町会長以外で渡しているケースは、それ以外に家が近いということだけでお渡ししているケースは、防災課への報告の中には入っておりません。","id":"exchange-032","title":"町会・自治会支援"},{"speaker":"木村委員","kind":"質問","question":"沢田委員からも質問がありましたけれども、何か震災対策とはちょっと外れますけれども、そういうことが可能なのかどうか。","respondent":"鈴木防災課長、齋藤庶務課長","answer":"学校として、総数として渡している鍵の数が一番多いところは、５本というところがあります。これは集まる町会が５つあるので、もしくはその鍵の場所を知っている役員の方が駆けつけて鍵をあけるというのが基本的なお約束だと聞いており… 一貫校になると２０台ぐらいのところがありまして、新しい学校であれば、常時、例えば８台、１０台のモニターが職員室で見えます。記録したものも、機械のハードのものにもよりますけれども、１週間、あるいは１カ月保存できているです。","id":"exchange-033"},{"speaker":"木村委員","kind":"質問・要望","question":"いろいろな問題で、学校は大きな震災が起きてから避難所を開設するまでにはどれぐらいの時間を必要とするものなのか、わかれば教えてほしいと求めました。","respondent":"鈴木防災課長","answer":"開設の要員を送るという２つあるかと思いますが、１時間から２時間ぐらいの、物の準備はできるかとは思います。先ほど教育次長からもお答えしましたように、発災からどれくらいの時間で避難所が開設されるというような基本的な時間の想定は、現在していないです。","id":"exchange-034"},{"speaker":"木村委員","kind":"質問・要望","question":"ですからそういう方が、これから、もしそういう大きな地震が来た場合には、多く出てくると思うんです。ですから、そういう意味では、やってほしいと求めました。","respondent":"鈴木防災課長、齋藤庶務課長","answer":"例えば１時間後に皆さん来ましょうとか、まずは集まってからと、必ずそういう行動をとるとは限りません。教育次長から説明したように、また… 迅速に対応できるように意識も変わっておりまして、震災時にどういった対応をするのが十分なのかと議論しておりますので、迅速な対応ができるように努めてまいります。","id":"exchange-035"},{"speaker":"高橋委員","kind":"確認","question":"校庭の壁とか、あと、古いバックネットとか、あと門柱とかでしょうか、そういうような非構造部材のほうの点検になるんでしょうか、ちょっとわかりませんけれども、そういったところの安全確認とその対応について、お尋ねします。","respondent":"齋藤庶務課長","answer":"今回も議会にご予算をいただきまして、非構造部材については着実に、２３区で最も早く取り組んでおります。ただ１個、計画的に進めておりますけれども、その点だけは少し私どもとしても苦労しています。","id":"exchange-036"},{"speaker":"吉田委員","kind":"意見","question":"１つだけお願いします。大間窪小学校の仮設のプレハブですとか、また清水台小学校のＢ１の補強工事中などということに関しての今の状況を、その辺のお考えをお願いしますとの意見を述べました。","respondent":"田村教育次長","answer":"さっきの庶務課長の説明が不十分だったかもしれないですけれども、仮設は、建物が重くないので耐震化は最高になっています。まだ若干平成２６年度まで時間かかりますけれども、避難のときには、御殿山小学校についてもご心配なくという形で対応できているという状況です。","id":"exchange-037"},{"speaker":"吉田委員","kind":"質問","question":"建設委員会でも１００％という数字が出ていなかった耐震化、地域の方が指定避難所になっても、全然困らないということで理解してよろしいか尋ねました。","respondent":"田村教育次長","answer":"そのように理解してもらって結構です。","id":"exchange-038"}]},{"id":"topic-02","title":"を聴取したいと思います。 品川区地域防災計画（平成２４年度修正）素案","agenda":"を聴取したいと思います。 品川区地域防災計画（平成２４年度修正）素案","exchanges":[{"speaker":"渡辺委員","kind":"提案","question":"できないもどうしても出てくる、私たちもいろいろ要望したけれども、それはまた上位計画との整合性がおありだということもありました。どうしても現場決裁、どう対応するかというものの弾力性というんですか、考え方を教えてほしいと求めました。","respondent":"高山防災計画担当課長","answer":"毎年見直しをする、そういった真摯な姿勢といいますか、多くを取り入れていくような姿勢で臨んでいきたいと考えております。そしてもう１つ、災害対応力ということに関しますと、いわゆる災害対応能力というようなものが問われていると考えますので。","id":"exchange-039"},{"speaker":"渡辺委員","kind":"提案","question":"もう１点、時期も大体発行から１年後なのか、時期はあるんでしょうか。そうすることによって私たちの議会提案も、想定で構いませんので、お願いしますとの意見を述べました。","respondent":"高山防災計画担当課長","answer":"今年のこの１１月の東京都の改定にとどまることなく、おそらく平成２５年中にもう一度、内容についての修正が図られると思います。平成１９年度以来の修正と冒頭申しましたが、平成２４年修正で満足することなく、見直しを継続的に図ってまいりたいと考えております。","id":"exchange-040"},{"speaker":"渡辺委員","kind":"質問","question":"各論については、もうこれ以上はないです。各論の質問はありませんので、時期の目安がついたら、いち早くお知らせほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"阿久津委員","kind":"質問","question":"動物の保護というところで、どう大きく変わったのかだけ、ご説明いただけますか尋ねました。","respondent":"高山防災計画担当課長","answer":"家族も同然ということでのペットの災害時の考え方なんですが、ペットフードの備蓄なども細かくは、これは飼い主の責務だと思います。要は趣旨として、そういった内容についての記載について、新たに設けさせていただいたところです。","id":"exchange-042"},{"speaker":"阿久津委員","kind":"質問・要望","question":"一応、こういうことも情報として提供した上で、ぜひ話し合いをしてほしいと求めました。ここのところは、要望も含めて、そこら辺の考え方を伺いたいと思います。","respondent":"高山防災計画担当課長","answer":"もちろん品川区だけで対応できない場合には、東京都の動物救援本部といったことで、広域的な救護の体制も整えるということになっております。","id":"exchange-043"},{"speaker":"阿久津委員","kind":"質問・要望","question":"これは自己完結でやるべきであって、いざというときにペットと避難できるよう、こういうこともやっているみたいなんです。そういう機会を持っていただいて、ぜひペットの飼い主に対しても周知をお願いしたいと思うんですが、いかがか尋ねました。","respondent":"高山防災計画担当課長","answer":"動物愛護週間などの機会を捉えまして、そういったペットのしつけでありますとか、災害時のお話などをさせていただいていると聞いております。獣医師会との連携というお話ですが、獣医師会とも継続的に意見交換、そしてご助言などをいただいてまいりたいと考えております。","id":"exchange-044"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それをどう防いでいくのかということがここの計画の中に入っていくということがすごく大事なんだと思いますけれども、どう災害を少なくしていくのかという予防対策に最重点を置くべきだと思うんですけれども、そこの考え方を１つお聞かせほしいと求めました。","respondent":"高山防災計画担当課長","answer":"予防段階で取り組むべき事項、そして災害直後の応急対応、それぞれにおいて必要なことについて計画を立てているところです。その意味では、かなり記載量が増していると読み取っていただけるのではないかと考えております。","id":"exchange-045"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"基本的なところでお伺いしたいのが、どこにどう書いてあるのかということが、そこが１点です。１万６,０００棟、具体的にどこからどういうふうにやっていくのかということがよくわからないんですけれども、その点について説明を求めました。","respondent":"高山防災計画担当課長","answer":"もう１つは、先ほどご説明申しました中で、そういったことも可能かと考えております。本案の公表に向けて検討していくところですので、こちらについては、今しばらくお待ち願えればと考えております。","id":"exchange-046"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"やはり、そこら辺の具体化というのがすごく大事になってくるんじゃないかなと思うんですけれども、その点はいかがでしょうか。不燃化領域をどうするというふうな具体的なところが出ているわけなんですけれども、この中ではどうしていくのかということを、説明を求めました。","respondent":"高山防災計画担当課長","answer":"延焼遮断帯の形成、そして初期消火力の強化といったことを、いわゆる内訳的に示しております。そういったものも１つ情報としながら、いわゆる施策を具体化するということに関しては、引き続き作業として進めてまいりたいと考えております。","id":"exchange-047"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その目標達成するための主な施策で、この目標でなぜこれが入ってくるのかというのがちょっとよくわからなかったので教えてほしいと求めました。継ぎ手の耐震化ですとか、上下水道の耐震化ですとか、その考え方についてもお聞かせほしいと求めました。","respondent":"高山防災計画担当課長","answer":"減災目標の２としての自衛隊との連携強化。それを早期に修復するといった点も、あわせて発災後の対応として必要だと考えておりますので、この点については特に矛盾はないと考えております。","id":"exchange-048"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"技術的には、巨大地震でも耐え得るだけの開発をされているということで伺いましたので、ぜひこの減災目標の中に入れていただけたらなと思っています。耐震化というのが７４ページのところで、前は、耐震化という言葉が消えてしまったのがなぜなのかということをちょっとお伺いしたいんです。","respondent":"高山防災計画担当課長","answer":"そういう意味では、区としての取り組みに何ら後退感があるということではなく、そういうふうに見つけにくくなったというレベルなのかと思います。","id":"exchange-049"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう点で言えば、後退しないということであれば、私は耐震化というのを、しっかりとこの地域防災計画の中に言葉として明記をしていただきたいと。そして、取り組みも進めていただきたいと思うんですけれども、いかがか尋ねました。","respondent":"高山防災計画担当課長","answer":"上位計画の考え方なりを共有するということで考えますと、区の施策自体を否定といいますか、後退させるということではないと考えております。具体的な取り組みの１つとして、災害を減ずるに当たっての重要な要素だと考えていますので、考えているところです。","id":"exchange-050"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"計画そのものの中にも、ぜひしっかりと耐震化を位置づけて、取り組みを進めていただきたいということでお願いしたいと思います。ちょっと細かい点なんですけれども、お願いできたらなと思っていますが、いかがか尋ねました。","respondent":"高山防災計画担当課長","answer":"地域別というご要望といいますか、ご意見ではありますが、いろいろ管理する上で、このような形での表というのを掲示させていただいているところです。現時点ではこのような形で、整備年度を中心とした表ということで、今回の素案は提出させていただいているところです。","id":"exchange-051"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"どういうものが一番わかりやすいのかというところで、もしもご検討いただけるようでしたら、よろしくお願いします。今４地域がこういう形で取り組まれているんですが、これをぜひ地域的に拡大をして、そこら辺の取り組みの今後の方向というのはいかがか尋ねました。","respondent":"品川防災整備担当課長","answer":"密集市街地整備事業の今後の展開ということですが、こちらは、１地区約１０年のスパンで事業を行っているものです。この辺の成果の状況を見て、またほかの地区ということになってくるという考えです。","id":"exchange-052"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"確実に公園ができたりとか、道幅が広がっていったりとか、そういうところではすごく地域にとっては喜ばれているんですよね。そこのところは、１つも公園がなくても、ぜひ拡大ということで取り組んでいただけたらと思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-053"},{"speaker":"井上委員","kind":"質問","question":"２行しか書いていないんですが、どのように認識されているのかということと、続けてもう一点だけ。４３ページの地域防災訓練のところで、この丸の３つ目のところに、その辺はいかがか尋ねました。","respondent":"鈴木防災課長、高山防災計画担当課長","answer":"実際に活用いただく方法について検討するということで、検討のための経費を、案として検討させていただいているところです。それから、実際の検討にあわせて、内容の表記は変更の予定をしております。１つ１つのことに十分対応できるかはお約束できるところではないんですが、一たび、これでパブリックコメントをします。","id":"exchange-054"},{"speaker":"井上委員","kind":"質問・要望","question":"これからパブリックコメントがあって、そういった表記についても、ぜひ検討ほしいと求めました。１９５ページで、その先にどういうふうなスケジュールで、お伺いしたいと思います。","respondent":"高山防災計画担当課長","answer":"総合計画ですので、その方向性のみの記載にとどまるというところは、このボランティアに限らずというところであるかと思います。この体制整備の主な中身になってまいりますが、体制の整備を図るといったことについては、変わりはございません。","id":"exchange-055"},{"speaker":"井上委員","kind":"質問","question":"最後に、放射性物質対策についてなんですけれども、現状、ここに放射性物質対策を入れていただいたことは評価をしています。もう少し区のマスタープランであれば、品川区の現状がどうなのかという表記になるのかなと思うんですが、どんなことか尋ねました。","respondent":"高山防災計画担当課長","answer":"３・１１のときも、避難もとどまることもできないような状況もあったと聞いておりますので、しかるべき適切な情報提供をしていくです。","id":"exchange-056"},{"speaker":"井上委員","kind":"質問・要望","question":"そこがどういうふうになっているのかということと、第２の被ばく線量の測定のところで、「被ばく線量等の測定等を実施する」と。区民の求めに応じというよりも、こういったところでイメージされているのか、少しこの辺を具体的に説明をいただければなと思うんですが。","respondent":"高山防災計画担当課長、野呂瀬環境課長","answer":"区立の病院などがないので、おそらくそういったところも含んでの対応になるかと思うんですが、区においては保健所が中心になろうかと考えております。被ばく線量の測定の実施につきましては… 区でできることはどういうことかということで、今回の放射線量も環境課が窓口になって、保健所等々とも連携をとりながらやってきたと。","id":"exchange-057"},{"speaker":"武内委員","kind":"質問","question":"この後、パブリックコメントが１２月１２日から始まるということなんですが、そうすると、これをもう一度、誤字脱字も含めて、パブリックコメントをかける前に、見直してチェックをするということはやられるんか尋ねました。","respondent":"高山防災計画担当課長","answer":"その上で、パブリックコメントをする前段階として、もう一度校正を入れます。ですので、仮にその段階で発見されたものについては対応するものです。","id":"exchange-058"},{"speaker":"武内委員","kind":"質問","question":"今見ていて、例えば２３ページの目標１のところの下のほうで、３つある中の２番目の「木造地域不燃化１０年プロジェクト」とありますね。「木密地域不燃化１０年プロジェクト」ではないのかと思うんだけれども、いかがか尋ねました。","respondent":"高山防災計画担当課長","answer":"速やかに対応します。","id":"exchange-059"},{"speaker":"武内委員","kind":"質問・要望","question":"これは、要望で結構です。もしつくるとすれば、スケジュール的にどんな感じで考えているのか、説明を求めました。","respondent":"高山防災計画担当課長","answer":"そして、平成１９年度のときと同じように、基礎的なデータなどを中心とした別冊編についてもつくっていくものです。２月の防災会議に、別冊ともども会議に付議いたしまして、ご承認をいただくといったスケジュールで進めてまいりたいと考えております。","id":"exchange-060"},{"speaker":"武内委員","kind":"質問","question":"それをどう考えていくのか。それがこの２月までの期間で１万数千の数を確保しようと考えているのか、それはそれということなのか、そこをちょっと説明を求めました。","respondent":"高山防災計画担当課長","answer":"こういった取り組みもやはり進めていく中で、避難者を減じていく、そういう努力も並行して必要なんだと考えております。地域も含めた対応ということを考えていきますと、そういった形で、区内にとらわれない避難者対策というのも進めていく必要があると考えております。","id":"exchange-061"},{"speaker":"武内委員","kind":"質問","question":"東京都はそこまで考えている。品川区も、それを今、場合によっては検討すると、こういうことでよろしいか尋ねました。","respondent":"高山防災計画担当課長","answer":"区界で地震がとまるわけではございませんので、当然首都を中心とする地震が起これば、被害も地域によって濃淡もあります。そのような考え方で計画するものですので、域外の被害も視野に入れた広域的な調整というのが、今回の大きな目玉となっているところです。","id":"exchange-062"},{"speaker":"武内委員","kind":"質問","question":"２月ぐらいまでに、非常にいろいろな話になってくるので、早目にご理解をいただかなければいけない。我々の委員会にもご報告いただきながら、早目にやっていかなければいけないのかなと思いますけれども、どうか尋ねました。","respondent":"高山防災計画担当課長","answer":"先ほど精査中と申しましたが、その精査の結果いかんによっては、その他の方策についても触れるような形でまとめてまいりたいと考えております。冒頭のほうに出てまいりましたように、順次改訂していく中で、この問題については対応してまいりたいと考えております。","id":"exchange-063"},{"speaker":"向委員","kind":"質問・要望","question":"ぱっと知りたいときにいかに情報を引き出せるかどうかができないと、もうちょっと目次とか、お考えはいかがなものでしょうか。教えていただけたらと思います。","respondent":"高山防災計画担当課長","answer":"いろいろと新しい考え方なども取り入れながら、先ほど委員のほうからも、テーマや字句の説明が冒頭にあっていいというお話もいただいております。","id":"exchange-064"},{"speaker":"向委員","kind":"質問・要望","question":"たまたま見つけたら１６３ページに当たるんですけれども、それがどこにどう書いてあるかというのが、本当に全くわからないんですよね。お忙しい中、検討していただけたらということで、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"},{"speaker":"南委員長","kind":"質問・要望","question":"二、確認させていただきたいと思っていますが、各所管で検討していただいたものを積み上げてまとめたという認識でいいんでしょうか。当委員会にも改めて事後になるんでしょうか、最終的な状況を把握させてほしいと求めましたので、ちょっとお願いさせてほしいと求めました。","respondent":"高山防災計画担当課長","answer":"区役所の内部におきましては、いわゆる分科会のような形式で、テーマごとに検討する場を持ちました。時期的には２月の後半になってしまうかと思うので、しかるべき決定案についてのご報告の機会を、また設けさせていただければと考えております。","id":"exchange-066"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/167861?Template=document&Id=6422#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=17&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":76073,"voices":155}},{"id":"h24-20121207-9","meetingId":"h24-cm12","date":"2012年12月7日","dateIso":"2012-12-07","committee":"文教委員会","time":"午後１時３５分～午後１時５５分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を7件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"南委員","kind":"確認","question":"ちょっと意見としてですけれども、そういう状況はちょっと発言をしておかなくてはいけないかなと思っています。学校教育職員のこの給与に関する条例というのは、改めて再度確認されましたので、そういうことで見ておきたいと思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"伊藤委員","kind":"確認","question":"内容の確認させてください。なぜ差異があるのかということが１点と、生じた減額分を加算するという、そういうややこしいことを何でするのかなという素直な疑問なんですが。","respondent":"太田指導課長","answer":"ちょっと説明が至らなくて申しわけございません。その部分においては、減額分も非常に多くなりますので、それを職責に応じて給与のほうに加算をするというような措置を東京都ではとられている。","id":"exchange-002"},{"speaker":"阿部委員","kind":"質問","question":"今の話の中で、住居手当、持家の方にも、つまりこれまでは払っていたということなんですよね。それは全国一律で、教員および公務員の場合はそのような感じになっていて、今回初めて住宅手当が見直されたという経過でよろしいんか尋ねました。","respondent":"太田指導課長","answer":"国のほうでは、平成２１年度以降、全面的に住居手当についてはなくしております。それを追随するというか、それに倣うということで、今回、東京都の人事委員会のほうが住居手当の見直しを図ったです。","id":"exchange-003"},{"speaker":"阿部委員","kind":"質問","question":"この住居手当見直しの減額分を補完するという時限的な措置なんですか。それとも、もう給料表として恒久的に措置するということなのか。","respondent":"田村教育次長","answer":"先ほど指導課長から説明したように、もともと１０ページの4)と5)の間を見てもらうと、国は持家に係る住居手当を廃止済みです。ですから、それが恒久的な制度で今後も続く、見直しを継続していくということです。","id":"exchange-004"},{"speaker":"渡部副委員長","kind":"確認","question":"今の話を聞いていて、であれば、そうかそうかでないかだけの確認なんですけれども、例えば４０歳の先生がいます。特別区人事委員会のほうが住宅手当に手をつけない限り、給与を余計にもらってしまうよというような形が今でき上がるということか尋ねました。","respondent":"太田指導課長","answer":"そのとおりです。","id":"exchange-005"},{"speaker":"高橋委員","kind":"意見","question":"要するに、3)にあるように、諸手当は行政の方と同じなんですよね、都の職員は。期末勤勉手当のところで差が出てくるのではないかなと思っているんですけれども、もし、今数字があれでしたら後ほどで結構ですとの意見を述べました。","respondent":"田村教育次長","answer":"後で、細かい数字は後ほど。","id":"exchange-006"},{"speaker":"南委員","kind":"意見","question":"限りなく、やはりこのままでいったら不況が続く、所得が減って購買力が落ちるという点ではいかがなものかと思います。しかし、一日でも早くそういう状況から脱出をしていくことが必要なのではないかというふうには思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/162678?Template=document&Id=4780#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":5827,"voices":29}},{"id":"h24-20121207-5","meetingId":"h24-cm12","date":"2012年12月7日","dateIso":"2012-12-07","committee":"総務委員会","time":"午後１時３６分～午後１時４８分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を3件整理しています。","topics":[{"id":"topic-01","title":"第８９号議案 職員の給与に関する条例の一部を改正する条例","agenda":"第８９号議案 職員の給与に関する条例の一部を改正する条例","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"前回の１１月の折に、給料表のところではなく、諸手当のことで、今後の検討課題であるというご答弁があったんですが、それと諸手当のところと、この間、何年ぐらいずっと引き下げが行われているのかなというあたりも説明を求めました。","respondent":"堀越人事課長","answer":"特別区の実情ですとか、ほかの団体の状況等見ながら、検討していく必要があるという形で意見が出されているところです。このような状況になってあります。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問・要望","question":"住宅手当制度、特別区とか他団体の状況を見てということでは、２５年度あたりにされるということなんでしょうか。この辺の待遇的なものがどうなのかというのを教えていただきたいのと、年金とか退職金なんかにもかなり影響するんか尋ねました。","respondent":"堀越人事課長","answer":"見直しの検討の時期ですけれども、時期を失することなく、検討していくという形になると思います。そういう意味で言えば、金額としては、この給与改定の影響を受けていくというものです。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"意見","question":"状況で判断してほしいなと思ったのが１点と、決して公務員も高いお給料ではないというところにおいて影響が大きいなというのを率直に感じております。何とか景気が回復して、給料が上がる方向になったらいいなと思っていますが、これは単純なる意見ですけれども、終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/579213?Template=document&Id=1934#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":3801,"voices":20}}]);
